export default HomeScreen;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { diagnosePlant } from '../services/geminiService';
import { Diagnosis } from '../types';
import { CameraIcon, UploadIcon, BackArrowIcon, SparklesIcon } from './icons';

interface ScanScreenProps {
  onDiagnosisComplete: (result: Diagnosis) => void;
  onBack: () => void;
}

const ScanScreen: React.FC<ScanScreenProps> = ({ onDiagnosisComplete, onBack }) => {
  const [imageSrc, setImageSrc] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const startCamera = useCallback(async () => {
    try {
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
        const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
        streamRef.current = stream;
        if (videoRef.current) {
            videoRef.current.srcObject = stream;
        }
    } catch (err) {
        console.error("Error accessing camera:", err);
        setError("Could not access the camera. Please check permissions and try again.");
    }
  }, []);

  useEffect(() => {
    startCamera();
    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
    };
  }, [startCamera]);

  const handleCapture = () => {
    if (videoRef.current) {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth;
      canvas.height = videoRef.current.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg');
        setImageSrc(dataUrl);
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
      }
    }
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setImageSrc(e.target?.result as string);
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleDiagnose = async () => {
    if (!imageSrc) return;
    setIsLoading(true);
    setError(null);
    try {
      const base64Data = imageSrc.split(',')[1];
      const mimeType = imageSrc.match(/data:([a-zA-Z0-9]+\/[a-zA-Z0-9-.+]+).*,.*/)?.[1] || 'image/jpeg';
      const result = await diagnosePlant(base64Data, mimeType);
      onDiagnosisComplete(result);
    } catch (err: any) {
      setError(err.message || 'An unknown error occurred.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleRetake = () => {
      setImageSrc(null);
      setError(null);
      startCamera();
  };

  return (
    <div className="flex flex-col items-center">
        <button onClick={onBack} className="absolute top-20 left-4 sm:top-24 sm:left-8 flex items-center gap-2 text-text-secondary-light dark:text-text-secondary-dark hover:text-primary dark:hover:text-primary transition-colors">
            <BackArrowIcon className="w-6 h-6" />
            <span>Home</span>
        </button>
      <div className="w-full max-w-lg bg-surface-light dark:bg-surface-dark p-6 rounded-2xl shadow-lg">
        {isLoading ? (
          <div className="flex flex-col items-center justify-center h-96">
            <SparklesIcon className="w-16 h-16 text-primary animate-spin" />
            <p className="mt-4 text-lg font-semibold">AI is analyzing your plant...</p>
            <p className="text-text-secondary-light dark:text-text-secondary-dark">This might take a moment.</p>
          </div>
        ) : (
          <>
            <div className="relative w-full aspect-square bg-gray-200 dark:bg-gray-700 rounded-lg overflow-hidden mb-4">
              {imageSrc ? (
                <img src={imageSrc} alt="Plant for diagnosis" className="w-full h-full object-cover" />
              ) : (
                <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover"></video>
              )}
            </div>

            {error && <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded-lg relative mb-4" role="alert">{error}</div>}

            {imageSrc ? (
              <div className="grid grid-cols-2 gap-4">
                <button onClick={handleRetake} className="w-full py-3 px-4 rounded-lg bg-gray-200 dark:bg-gray-600 hover:bg-gray-300 dark:hover:bg-gray-500 font-semibold transition-colors">
                  Retake Photo
                </button>
                <button onClick={handleDiagnose} className="w-full flex items-center justify-center gap-2 py-3 px-4 rounded-lg bg-primary hover:bg-primary-dark text-white font-bold transition-colors">
                  <SparklesIcon className="w-5 h-5"/>
                  Diagnose
                </button>
              </div>
            ) : (
              <div className="grid grid-cols-2 gap-4">
                <button onClick={handleCapture} className="w-full flex items-center justify-center gap-2 py-3 px-4 rounded-lg bg-primary hover:bg-primary-dark text-white font-bold transition-colors">
                  <CameraIcon className="w-5 h-5"/>
                  Capture
                </button>
                <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center justify-center gap-2 py-3 px-4 rounded-lg bg-secondary hover:bg-secondary-dark dark:text-gray-900 font-bold transition-colors">
                  <UploadIcon className="w-5 h-5"/>
                  Upload
                </button>
                <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*" className="hidden" />
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
};

export default ScanScreen;

import React from 'react';
import { Diagnosis } from '../types';
import { SparklesIcon, LeafIcon } from './icons';

interface DiagnosisResultScreenProps {
  diagnosis: Diagnosis;
  onSave: () => void;
  onDiscard: () => void;
}

const DiagnosisResultScreen: React.FC<DiagnosisResultScreenProps> = ({ diagnosis, onSave, onDiscard }) => {

  const confidenceColor = diagnosis.confidence > 0.75 ? 'text-green-500' : diagnosis.confidence > 0.5 ? 'text-yellow-500' : 'text-red-500';

  const renderList = (title: string, items: string[]) => {
    if (!items || items.length === 0) return null;
    return (
      <div className="mt-4">
        <h4 className="font-bold text-lg text-text-light dark:text-text-dark">{title}</h4>
        <ul className="list-disc list-inside mt-2 space-y-1 text-text-secondary-light dark:text-text-secondary-dark">
          {items.map((item, index) => <li key={index}>{item}</li>)}
        </ul>
      </div>
    );
  };

  return (
    <div className="animate-fade-in space-y-6">
      <div className="p-6 bg-surface-light dark:bg-surface-dark rounded-2xl shadow-lg text-center">
        <h2 className="text-3xl font-bold text-primary">{diagnosis.plantName}</h2>
        <div className={`mt-2 text-2xl font-semibold ${diagnosis.isHealthy ? 'text-green-500' : 'text-orange-500'}`}>
          {diagnosis.isHealthy ? 'Healthy' : diagnosis.disease}
        </div>
        {!diagnosis.isHealthy && (
           <div className="mt-2 flex items-center justify-center gap-2 text-text-secondary-light dark:text-text-secondary-dark">
            <span>Confidence:</span>
            <span className={`font-bold ${confidenceColor}`}>{Math.round(diagnosis.confidence * 100)}%</span>
          </div>
        )}
      </div>

      <InfoCard title="AI Diagnosis Summary">
        <p className="text-text-secondary-light dark:text-text-secondary-dark">{diagnosis.description}</p>
      </InfoCard>

      {!diagnosis.isHealthy && (
        <>
          <InfoCard title="Symptoms">
            {renderList('', diagnosis.symptoms)}
          </InfoCard>

          <InfoCard title="Treatment Plan">
            {renderList('Organic Solutions', diagnosis.treatments.organic)}
            {renderList('Chemical Solutions', diagnosis.treatments.chemical)}
          </InfoCard>

          <InfoCard title="Prevention Tips">
            {renderList('', diagnosis.prevention)}
          </InfoCard>
        </>
      )}

      <div className="sticky bottom-4 grid grid-cols-2 gap-4 bg-background-light/80 dark:bg-background-dark/80 backdrop-blur-sm py-2 rounded-xl">
        <button onClick={onDiscard} className="w-full py-3 px-4 rounded-lg bg-gray-200 dark:bg-gray-600 hover:bg-gray-300 dark:hover:bg-gray-500 font-semibold transition-colors">
          Scan Another
        </button>
        <button onClick={onSave} className="w-full flex items-center justify-center gap-2 py-3 px-4 rounded-lg bg-primary hover:bg-primary-dark text-white font-bold transition-colors">
          <LeafIcon className="w-5 h-5"/>
          Save to My Garden
        </button>
      </div>
    </div>
  );
};

interface InfoCardProps {
    title: string;
    children: React.ReactNode;
}

const InfoCard: React.FC<InfoCardProps> = ({ title, children }) => (
    <div className="p-6 bg-surface-light dark:bg-surface-dark rounded-2xl shadow-lg">
        <div className="flex items-center gap-2">
            <SparklesIcon className="w-6 h-6 text-secondary" />
            <h3 className="text-xl font-bold text-text-light dark:text-text-dark">{title}</h3>
        </div>
        <div className="mt-4">{children}</div>
    </div>
);

export default DiagnosisResultScreen;

import React from 'react';
import { HistoryItem } from '../types';
import { BackArrowIcon, LeafIcon, TrashIcon } from './icons';

interface HistoryScreenProps {
  history: HistoryItem[];
  onBack: () => void;
  onClearHistory: () => void;
}

const HistoryScreen: React.FC<HistoryScreenProps> = ({ history, onBack, onClearHistory }) => {
  return (
    <div className="animate-fade-in">
        <div className="flex justify-between items-center mb-6">
            <button onClick={onBack} className="flex items-center gap-2 text-text-secondary-light dark:text-text-secondary-dark hover:text-primary dark:hover:text-primary transition-colors">
                <BackArrowIcon className="w-6 h-6" />
                <span className="text-lg">Home</span>
            </button>
            <h2 className="text-3xl font-bold text-center text-primary">My Garden History</h2>
             <button
                onClick={onClearHistory}
                disabled={history.length === 0}
                className="flex items-center gap-2 py-2 px-4 rounded-lg text-red-500 hover:bg-red-100 dark:hover:bg-red-900/50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                aria-label="Clear history"
            >
                <TrashIcon className="w-5 h-5" />
                <span>Clear</span>
            </button>
        </div>

      {history.length === 0 ? (
        <div className="text-center py-20 px-6 bg-surface-light dark:bg-surface-dark rounded-2xl shadow-lg">
          <LeafIcon className="w-16 h-16 mx-auto text-gray-400" />
          <h3 className="mt-4 text-2xl font-semibold">Your garden is empty.</h3>
          <p className="mt-2 text-text-secondary-light dark:text-text-secondary-dark">
            Start by scanning a plant to save its health record here.
          </p>
          <button onClick={onBack} className="mt-6 py-2 px-6 bg-primary text-white font-bold rounded-lg hover:bg-primary-dark transition-colors">
            Start Scanning
          </button>
        </div>
      ) : (
        <div className="space-y-4">
          {history.map((item) => (
            <HistoryItemCard key={item.id} item={item} />
          ))}
        </div>
      )}
    </div>
  );
};

const HistoryItemCard: React.FC<{ item: HistoryItem }> = ({ item }) => {
  const diagnosisDate = new Date(item.timestamp).toLocaleDateString(undefined, {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  });

  return (
    <div className="bg-surface-light dark:bg-surface-dark p-4 rounded-xl shadow-md flex items-center justify-between transition-transform hover:scale-105 duration-200">
      <div className="flex items-center gap-4">
        <div className={`p-3 rounded-full ${item.isHealthy ? 'bg-green-100 dark:bg-green-900' : 'bg-orange-100 dark:bg-orange-900'}`}>
            <LeafIcon className={`w-8 h-8 ${item.isHealthy ? 'text-green-500' : 'text-orange-500'}`} />
        </div>
        <div>
          <h4 className="font-bold text-lg">{item.plantName}</h4>
          <p className={`font-semibold ${item.isHealthy ? 'text-green-600 dark:text-green-400' : 'text-orange-600 dark:text-orange-400'}`}>
            {item.isHealthy ? 'Healthy' : item.disease}
          </p>
          <p className="text-sm text-text-secondary-light dark:text-text-secondary-dark">{diagnosisDate}</p>
        </div>
      </div>
       <div className="text-right">
        <span className="text-sm font-medium text-text-secondary-light dark:text-text-secondary-dark">Confidence</span>
        <p className="font-bold text-lg">{Math.round(item.confidence * 100)}%</p>
       </div>
    </div>
  );
};


export default HistoryScreen;

