import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { Diagnosis } from '../types';

const API_KEY = process.env.API_KEY;

if (!API_KEY) {
  throw new Error("API_KEY environment variable is not set");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

const diagnosisSchema = {
    type: Type.OBJECT,
    properties: {
        plantName: { type: Type.STRING, description: "The common name of the plant. If unsure, state 'Unknown Plant'." },
        isHealthy: { type: Type.BOOLEAN, description: "True if the plant appears healthy, false otherwise." },
        // Fix: Removed unsupported `nullable` property. The model can still return a null value for this field.
        disease: { type: Type.STRING, description: "The common name of the disease or pest. Null if healthy." },
        confidence: { type: Type.NUMBER, description: "Confidence in the diagnosis, from 0.0 to 1.0." },
        description: { type: Type.STRING, description: "A brief, easy-to-understand summary of the diagnosis for a non-expert." },
        symptoms: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            description: "A list of key symptoms observed or typical for the diagnosed issue."
        },
        treatments: {
            type: Type.OBJECT,
            properties: {
                organic: {
                    type: Type.ARRAY,
                    items: { type: Type.STRING },
                    description: "A list of organic/natural treatment suggestions."
                },
                chemical: {
                    type: Type.ARRAY,
                    items: { type: Type.STRING },
                    description: "A list of chemical treatment suggestions."
                },
            },
        },
        prevention: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            description: "A list of tips to prevent this issue in the future."
        },
    },
    required: ["plantName", "isHealthy", "disease", "confidence", "description", "symptoms", "treatments", "prevention"],
};

const fileToGenerativePart = (base64: string, mimeType: string) => {
  return {
    inlineData: {
      data: base64,
      mimeType
    },
  };
};

export const diagnosePlant = async (base64Image: string, mimeType: string): Promise<Diagnosis> => {
  try {
    const imagePart = fileToGenerativePart(base64Image, mimeType);

    const prompt = `You are an expert botanist and plant pathologist named EcoMed AI. Your task is to analyze the provided image of a plant.

Based on the image, provide a diagnosis. Respond with only a valid JSON object that strictly adheres to the defined schema. Do not include any text, markdown formatting, or explanations outside of the JSON object.`;

    const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: { parts: [imagePart, { text: prompt }] },
        config: {
            responseMimeType: "application/json",
            responseSchema: diagnosisSchema,
        },
    });

    const text = response.text;
    if (!text) {
        throw new Error("API returned an empty response.");
    }

    const parsedJson = JSON.parse(text);
    return parsedJson as Diagnosis;

  } catch (error) {
    console.error("Error diagnosing plant:", error);
    throw new Error("Failed to get a diagnosis from the AI. The plant might be unclear in the image, or there was a network issue. Please try again.");
  }
};

import React, { useState, useEffect, useCallback } from 'react';
import HomeScreen from './components/HomeScreen';
import ScanScreen from './components/ScanScreen';
import DiagnosisResultScreen from './components/DiagnosisResultScreen';
import HistoryScreen from './components/HistoryScreen';
import FeedbackScreen from './components/FeedbackScreen';
import Header from './components/Header';
import { Diagnosis, HistoryItem } from './types';
import { LeafIcon } from './components/icons';

type View = 'home' | 'scan' | 'result' | 'history' | 'feedback';
type Theme = 'light' | 'dark';

const App: React.FC = () => {
  const [theme, setTheme] = useState<Theme>('light');
  const [currentView, setCurrentView] = useState<View>('home');
  const [diagnosisResult, setDiagnosisResult] = useState<Diagnosis | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const savedTheme = localStorage.getItem('theme') as Theme;
    if (savedTheme) {
      setTheme(savedTheme);
    }

    try {
      const savedHistory = localStorage.getItem('plantHistory');
      if (savedHistory) {
        setHistory(JSON.parse(savedHistory));
      }
    } catch (error) {
      console.error("Failed to parse history from localStorage", error);
    }

    // Simulate initial loading
    setTimeout(() => setIsLoading(false), 1000);
  }, []);

  useEffect(() => {
    localStorage.setItem('theme', theme);
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [theme]);

  const handleDiagnosisComplete = useCallback((result: Diagnosis) => {
    setDiagnosisResult(result);
    setCurrentView('result');
  }, []);

  const handleSaveDiagnosis = useCallback(() => {
    if (diagnosisResult) {
      const newHistoryItem: HistoryItem = {
        ...diagnosisResult,
        id: new Date().toISOString(),
        timestamp: new Date().toISOString(),
        image: '', // In a real app, you would store the image data here
      };
      const updatedHistory = [newHistoryItem, ...history];
      setHistory(updatedHistory);
      localStorage.setItem('plantHistory', JSON.stringify(updatedHistory));
      setDiagnosisResult(null);
      setCurrentView('history');
    }
  }, [diagnosisResult, history]);

  const handleDiscardDiagnosis = useCallback(() => {
    setDiagnosisResult(null);
    setCurrentView('scan');
  }, []);

  const handleClearHistory = useCallback(() => {
    setHistory([]);
    localStorage.removeItem('plantHistory');
  }, []);

  if (isLoading) {
    return (
      <div className={`flex flex-col items-center justify-center min-h-screen w-full transition-colors duration-500 ${theme === 'light' ? 'bg-background-light' : 'bg-background-dark'}`}>
        <LeafIcon className="w-24 h-24 text-primary animate-pulse" />
        <h1 className="mt-4 text-3xl font-bold text-primary">EcoMed</h1>
        <p className="text-text-secondary-light dark:text-text-secondary-dark">Your personal plant doctor.</p>
      </div>
    );
  }

  const renderContent = () => {
    switch (currentView) {
      case 'scan':
        return <ScanScreen onDiagnosisComplete={handleDiagnosisComplete} onBack={() => setCurrentView('home')} />;
      case 'result':
        return diagnosisResult ? <DiagnosisResultScreen diagnosis={diagnosisResult} onSave={handleSaveDiagnosis} onDiscard={handleDiscardDiagnosis} /> : <HomeScreen onNavigate={setCurrentView} />;
      case 'history':
        return <HistoryScreen history={history} onBack={() => setCurrentView('home')} onClearHistory={handleClearHistory} />;
      case 'feedback':
        return <FeedbackScreen onBack={() => setCurrentView('home')} />;
      case 'home':
      default:
        return <HomeScreen onNavigate={setCurrentView} />;
    }
  };

  return (
    <div className="min-h-screen w-full bg-background-light dark:bg-background-dark text-text-light dark:text-text-dark transition-colors duration-500">
      <Header theme={theme} setTheme={setTheme} />
      <main className="p-4 sm:p-6 md:p-8 max-w-4xl mx-auto">
        {renderContent()}
      </main>
      <footer className="text-center p-4 text-text-secondary-light dark:text-text-secondary-dark text-sm">
        <p>Powered by AI. For educational purposes only.</p>
      </footer>
    </div>
  );
};

export default App;

export interface Diagnosis {
  plantName: string;
  isHealthy: boolean;
  disease: string | null;
  confidence: number;
  description: string;
  symptoms: string[];
  treatments: {
    organic: string[];
