                        className="h-full bg-gradient-to-r from-secondary to-primary transition-all duration-500 ease-out"
                        style={{ width: `${progress}%` }}
                    ></div>
                </div>

                {step === 1 ? (
                    <form onSubmit={handleSubmit} className="p-8 space-y-8">
                        <div>
                            <h2 className="text-3xl font-bold text-center text-text-light dark:text-text-dark">Share Your Feedback</h2>
                            <p className="text-center text-text-secondary-light dark:text-text-secondary-dark mt-1">How was your experience?</p>
                        </div>

                        <div className="space-y-4">
                            <label className="font-semibold text-text-light dark:text-text-dark">How would you describe it?</label>
                            <div className="flex justify-between">
                                {EMOJI_REACTIONS.map(({name, emoji}) => (
                                    <button 
                                        key={name} 
                                        type="button"
                                        onClick={() => setReaction(name)}
                                        className={`p-2 rounded-full text-3xl transition-all duration-200 ${reaction === name ? 'bg-primary/20 scale-125' : 'hover:scale-110 hover:bg-slate-200 dark:hover:bg-slate-700'}`}
                                    >
                                        {emoji}
                                    </button>
                                ))}
                            </div>
                        </div>

                        <div className="space-y-4">
                             <label className="font-semibold text-text-light dark:text-text-dark">Rate our app</label>
                             <div className="flex justify-center items-center space-x-2" onMouseLeave={() => setHoverRating(0)}>
                                {[1, 2, 3, 4, 5].map((star) => (
                                    <StarIcon 
                                        key={star}
                                        className={`w-10 h-10 cursor-pointer transition-all duration-150 ${ (hoverRating || rating) >= star ? 'text-yellow-400 fill-yellow-400' : 'text-slate-400 dark:text-slate-500' }`}
                                        onClick={() => setRating(star)}
                                        onMouseEnter={() => setHoverRating(star)}
                                    />
                                ))}
                             </div>
                        </div>

                        <div className="relative">
                            <textarea
                                id="comment"
                                value={comment}
                                onChange={(e) => setComment(e.target.value)}
                                className="peer block w-full h-28 px-4 py-3 bg-slate-100 dark:bg-slate-700/50 rounded-lg border-2 border-transparent focus:border-primary focus:outline-none focus:ring-0 transition-colors"
                                placeholder=" "
                            ></textarea>
                            <label htmlFor="comment" className="absolute text-text-secondary-light dark:text-text-secondary-dark left-4 top-3 transition-all duration-300 peer-placeholder-shown:top-3 peer-placeholder-shown:text-base peer-focus:-top-2.5 peer-focus:text-sm peer-focus:text-primary dark:peer-focus:text-secondary-light peer-[:not(:placeholder-shown)]:-top-2.5 peer-[:not(:placeholder-shown)]:text-sm bg-background-light dark:bg-surface-dark px-1">
                                Any other feedback?
                            </label>
                        </div>

                        <button type="submit" className="w-full py-3 px-4 rounded-xl bg-gradient-to-r from-secondary to-primary text-white font-bold text-lg shadow-lg hover:shadow-primary/50 dark:hover:shadow-primary/30 transform hover:scale-105 transition-all duration-300 focus:outline-none focus:ring-4 focus:ring-primary/50">
                            Submit Feedback
                        </button>
                    </form>
                ) : (
                    <div className="p-8 flex flex-col items-center justify-center text-center h-96">
                        <div className="w-24 h-24 bg-primary/20 rounded-full flex items-center justify-center mb-6">
                            <CheckIcon className="w-16 h-16 text-primary animate-check"/>
                        </div>
                        <h2 className="text-3xl font-bold text-text-light dark:text-text-dark">Thank You!</h2>
                        <p className="text-text-secondary-light dark:text-text-secondary-dark mt-2">Your feedback helps us improve EcoMed for everyone.</p>
                    </div>
                )}
            </div>
        </div>
    );
};

