import React, { useState, useRef, useEffect, useCallback } from 'react';
import { diagnosePlant } from '../services/geminiService';
import { Diagnosis } from '../types';
import { CameraIcon, UploadIcon, BackArrowIcon, SparklesIcon } from './icons';

interface ScanScreenProps {
  onDiagnosisComplete: (result: Diagnosis) => void;
  onBack: () => void;
}

const ScanScreen: React.FC<ScanScreenProps> = ({ onDiagnosisComplete, onBack }) => {
  const [imageSrc, setImageSrc] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const startCamera = useCallback(async () => {
    try {
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
        const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
        streamRef.current = stream;
        if (videoRef.current) {
            videoRef.current.srcObject = stream;
        }
    } catch (err) {
        console.error("Error accessing camera:", err);
        setError("Could not access the camera. Please check permissions and try again.");
    }
  }, []);

  useEffect(() => {
    startCamera();
    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
    };
  }, [startCamera]);

  const handleCapture = () => {
    if (videoRef.current) {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth;
      canvas.height = videoRef.current.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg');
        setImageSrc(dataUrl);
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
      }
    }
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setImageSrc(e.target?.result as string);
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleDiagnose = async () => {
    if (!imageSrc) return;
    setIsLoading(true);
    setError(null);
    try {
      const base64Data = imageSrc.split(',')[1];
      const mimeType = imageSrc.match(/data:([a-zA-Z0-9]+\/[a-zA-Z0-9-.+]+).*,.*/)?.[1] || 'image/jpeg';
      const result = await diagnosePlant(base64Data, mimeType);
      onDiagnosisComplete(result);
    } catch (err: any) {
      setError(err.message || 'An unknown error occurred.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleRetake = () => {
      setImageSrc(null);
      setError(null);
      startCamera();
  };

  return (
    <div className="flex flex-col items-center">
        <button onClick={onBack} className="absolute top-4 left-0 flex items-center gap-2 text-text-secondary-light dark:text-text-secondary-dark hover:text-primary dark:hover:text-primary transition-colors">
            <BackArrowIcon className="w-6 h-6" />
            <span>Home</span>
        </button>
      <div className="w-full max-w-lg bg-surface-light dark:bg-surface-dark p-6 rounded-2xl shadow-lg mt-8">
        {isLoading ? (
          <div className="flex flex-col items-center justify-center h-96">
            <SparklesIcon className="w-16 h-16 text-primary animate-spin" />
            <p className="mt-4 text-lg font-semibold">AI is analyzing your plant...</p>
            <p className="text-text-secondary-light dark:text-text-secondary-dark">This might take a moment.</p>
          </div>
        ) : (
          <>
            <div className="relative w-full aspect-square bg-gray-200 dark:bg-gray-700 rounded-lg overflow-hidden mb-4">
              {imageSrc ? (
                <img src={imageSrc} alt="Plant for diagnosis" className="w-full h-full object-cover" />
              ) : (
                <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover"></video>
              )}
            </div>

            {error && <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded-lg relative mb-4" role="alert">{error}</div>}

            {imageSrc ? (
              <div className="grid grid-cols-2 gap-4">
                <button onClick={handleRetake} className="w-full py-3 px-4 rounded-lg bg-gray-200 dark:bg-gray-600 hover:bg-gray-300 dark:hover:bg-gray-500 font-semibold transition-colors">
                  Retake Photo
                </button>
                <button onClick={handleDiagnose} className="w-full flex items-center justify-center gap-2 py-3 px-4 rounded-lg bg-primary hover:bg-primary-dark text-white font-bold transition-colors">
                  <SparklesIcon className="w-5 h-5"/>
                  Diagnose
                </button>
              </div>
            ) : (
              <div className="grid grid-cols-2 gap-4">
                <button onClick={handleCapture} className="w-full flex items-center justify-center gap-2 py-3 px-4 rounded-lg bg-primary hover:bg-primary-dark text-white font-bold transition-colors">
                  <CameraIcon className="w-5 h-5"/>
                  Capture
                </button>
                <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center justify-center gap-2 py-3 px-4 rounded-lg bg-secondary hover:bg-secondary-dark dark:text-gray-900 font-bold transition-colors">
                  <UploadIcon className="w-5 h-5"/>
                  Upload
                </button>
                <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*" className="hidden" />
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
};

export default ScanScreen;

import React, { useState, useEffect } from 'react';
import { Diagnosis } from '../types';
import { SparklesIcon, LeafIcon, ChevronDownIcon } from './icons';

interface DiagnosisResultScreenProps {
  diagnosis: Diagnosis;
  onSave: () => void;
  onDiscard: () => void;
}

// Sub-component: Animated Circular Progress for confidence score
const CircularProgress: React.FC<{ progress: number; color: string }> = ({ progress, color }) => {
    const [displayProgress, setDisplayProgress] = useState(0);
    const size = 120;
    const strokeWidth = 10;
    const radius = (size - strokeWidth) / 2;
    const circumference = 2 * Math.PI * radius;
    const offset = circumference - (displayProgress / 100) * circumference;

    useEffect(() => {
        const timer = setTimeout(() => setDisplayProgress(progress), 100);
        return () => clearTimeout(timer);
    }, [progress]);

    return (
        <div className="relative" style={{ width: size, height: size }}>
            <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
                <circle className="stroke-slate-200 dark:stroke-slate-700" fill="transparent" strokeWidth={strokeWidth} r={radius} cx={size / 2} cy={size / 2} />
                <circle
                    className="transition-all duration-1000 ease-out"
                    stroke={color}
                    fill="transparent"
                    strokeWidth={strokeWidth}
                    strokeDasharray={circumference}
                    strokeDashoffset={offset}
                    strokeLinecap="round"
                    r={radius}
                    cx={size / 2}
                    cy={size / 2}
                    transform={`rotate(-90 ${size / 2} ${size / 2})`}
                />
            </svg>
            <div className="absolute inset-0 flex flex-col items-center justify-center">
                <span className="text-3xl font-bold" style={{ color }}>{Math.round(displayProgress)}%</span>
                <span className="text-sm text-text-secondary-light dark:text-text-secondary-dark">Confidence</span>
            </div>
        </div>
    );
};

// Sub-component: Accordion for treatment plan
const Accordion: React.FC<{ title: string; children: React.ReactNode; icon: React.ReactNode; }> = ({ title, children, icon }) => {
    const [isOpen, setIsOpen] = useState(false);
    return (
        <div className="border-t border-slate-200 dark:border-slate-700">
            <button onClick={() => setIsOpen(!isOpen)} className="flex justify-between items-center w-full py-4 text-left font-semibold text-lg hover:bg-slate-50 dark:hover:bg-slate-700/50 px-2 rounded-md">
                <div className="flex items-center gap-3">
                    {icon}
                    <span>{title}</span>
                </div>
                <ChevronDownIcon className={`w-6 h-6 transition-transform duration-300 ${isOpen ? 'rotate-180' : ''}`} />
