const DiagnosisResultScreen: React.FC<DiagnosisResultScreenProps> = ({ diagnosis, onSave, onDiscard }) => {
    const confidenceValue = Math.round(diagnosis.confidence * 100);
    const confidenceColor = confidenceValue > 75 ? '#22c55e' : confidenceValue > 50 ? '#f59e0b' : '#ef4444';

    const renderList = (items: string[]) => {
        if (!items || items.length === 0) return <p className="text-text-secondary-light dark:text-text-secondary-dark italic">No specific recommendations provided.</p>;
        return (
            <ul className="list-disc list-inside space-y-2 text-text-secondary-light dark:text-text-secondary-dark">
                {items.map((item, index) => <li key={index}>{item}</li>)}
            </ul>
        );
    };

    return (
        <div className="space-y-6">
            <div className="p-6 bg-surface-light dark:bg-surface-dark rounded-2xl shadow-lg flex flex-col md:flex-row items-center gap-6 animate-fade-in">
                <div className="flex-grow text-center md:text-left">
                    <h2 className="text-4xl font-bold text-primary">{diagnosis.plantName}</h2>
                    <div className={`mt-2 text-2xl font-semibold ${diagnosis.isHealthy ? 'text-green-500' : 'text-orange-500'}`}>
                        {diagnosis.isHealthy ? 'Healthy' : diagnosis.disease}
                    </div>
                </div>
                {!diagnosis.isHealthy && (
                    <div className="flex-shrink-0">
                        <CircularProgress progress={confidenceValue} color={confidenceColor} />
                    </div>
                )}
            </div>

            <InfoCard title="AI Diagnosis Summary" delay={100}>
                <p className="text-text-secondary-light dark:text-text-secondary-dark">{diagnosis.description}</p>
            </InfoCard>

            {!diagnosis.isHealthy && (
                <>
                    <InfoCard title="Symptoms" delay={200}>
                        {renderList(diagnosis.symptoms)}
                    </InfoCard>

                    <InfoCard title="Treatment Plan" delay={300}>
                        <Accordion title="Organic Solutions" icon={<LeafIcon className="w-6 h-6 text-green-500" />}>
                            {renderList(diagnosis.treatments.organic)}
                        </Accordion>
                        <Accordion title="Chemical Solutions" icon={<SparklesIcon className="w-6 h-6 text-blue-500" />}>
                            {renderList(diagnosis.treatments.chemical)}
                        </Accordion>
                    </InfoCard>

                    <InfoCard title="Prevention Tips" delay={400}>
                        {renderList(diagnosis.prevention)}
                    </InfoCard>
                </>
            )}

            <div className="sticky bottom-4 grid grid-cols-2 gap-4 bg-background-light/80 dark:bg-background-dark/80 backdrop-blur-sm py-2 rounded-xl animate-fade-in" style={{animationDelay: '500ms'}}>
                <button onClick={onDiscard} className="w-full py-3 px-4 rounded-lg bg-gray-200 dark:bg-gray-600 hover:bg-gray-300 dark:hover:bg-gray-500 font-semibold transition-colors">
                    Scan Another
                </button>
                <button onClick={onSave} className="w-full flex items-center justify-center gap-2 py-3 px-4 rounded-lg bg-primary hover:bg-primary-dark text-white font-bold transition-colors">
                    <LeafIcon className="w-5 h-5"/>
                    Save to My Garden
                </button>
            </div>
        </div>
    );
};

