import React, { useState, useMemo, useEffect } from 'react';
import { BackArrowIcon, StarIcon, CheckIcon } from './icons';

interface FeedbackScreenProps {
    onBack: () => void;
}

const EMOJI_REACTIONS = [
    { name: 'disappointed', emoji: '😞' },
    { name: 'neutral', emoji: '😐' },
    { name: 'satisfied', emoji: '😊' },
    { name: 'happy', emoji: '😄' },
    { name: 'amazed', emoji: '🤩' },
];

const FeedbackScreen: React.FC<FeedbackScreenProps> = ({ onBack }) => {
    const [step, setStep] = useState(1);
    const [rating, setRating] = useState(0);
    const [hoverRating, setHoverRating] = useState(0);
    const [reaction, setReaction] = useState<string | null>(null);
    const [comment, setComment] = useState('');

    const progress = useMemo(() => {
        const completed = [rating > 0, reaction !== null, comment.trim().length > 5].filter(Boolean).length;
        return (completed / 3) * 100;
    }, [rating, reaction, comment]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setStep(2);
    };

    useEffect(() => {
        if (step === 2) {
            const timer = setTimeout(() => {
                onBack();
            }, 3000);
            return () => clearTimeout(timer);
        }
    }, [step, onBack]);

    return (
        <div className="relative z-10 flex flex-col items-center justify-center min-h-[calc(100vh-240px)] animate-fade-in">
            <div className="feedback-bg" aria-hidden="true"></div>

            <button onClick={onBack} className="absolute top-4 left-0 flex items-center gap-2 text-text-secondary-light dark:text-text-secondary-dark hover:text-primary dark:hover:text-primary transition-colors z-20">
                <BackArrowIcon className="w-6 h-6" />
                <span>Home</span>
            </button>

            <div className="relative w-full max-w-md bg-white/50 dark:bg-slate-800/50 backdrop-blur-xl rounded-3xl shadow-2xl border border-white/20 dark:border-slate-700/50 overflow-hidden">
                <div className="w-full h-2 bg-slate-200 dark:bg-slate-700">
                    <div
                        className="h-full bg-gradient-to-r from-secondary to-primary transition-all duration-500 ease-out"
                        style={{ width: `${progress}%` }}
                    ></div>
                </div>

                {step === 1 ? (
                    <form onSubmit={handleSubmit} className="p-8 space-y-8">
                        <div>
                            <h2 className="text-3xl font-bold text-center text-text-light dark:text-text-dark">Share Your Feedback</h2>
                            <p className="text-center text-text-secondary-light dark:text-text-secondary-dark mt-1">How was your experience?</p>
                        </div>

                        <div className="space-y-4">
                            <label className="font-semibold text-text-light dark:text-text-dark">How would you describe it?</label>
                            <div className="flex justify-between">
                                {EMOJI_REACTIONS.map(({name, emoji}) => (
                                    <button 
                                        key={name} 
                                        type="button"
                                        onClick={() => setReaction(name)}
                                        className={`p-2 rounded-full text-3xl transition-all duration-200 ${reaction === name ? 'bg-primary/20 scale-125' : 'hover:scale-110 hover:bg-slate-200 dark:hover:bg-slate-700'}`}
                                    >
                                        {emoji}
                                    </button>
                                ))}
                            </div>
                        </div>

                        <div className="space-y-4">
                             <label className="font-semibold text-text-light dark:text-text-dark">Rate our app</label>
                             <div className="flex justify-center items-center space-x-2" onMouseLeave={() => setHoverRating(0)}>
                                {[1, 2, 3, 4, 5].map((star) => (
                                    <StarIcon 
                                        key={star}
                                        className={`w-10 h-10 cursor-pointer transition-all duration-150 ${ (hoverRating || rating) >= star ? 'text-yellow-400 fill-yellow-400' : 'text-slate-400 dark:text-slate-500' }`}
                                        onClick={() => setRating(star)}
                                        onMouseEnter={() => setHoverRating(star)}
                                    />
                                ))}
                             </div>
                        </div>

                        <div className="relative">
                            <textarea
                                id="comment"
                                value={comment}
                                onChange={(e) => setComment(e.target.value)}
                                className="peer block w-full h-28 px-4 py-3 bg-slate-100 dark:bg-slate-700/50 rounded-lg border-2 border-transparent focus:border-primary focus:outline-none focus:ring-0 transition-colors"
                                placeholder=" "
                            ></textarea>
                            <label htmlFor="comment" className="absolute text-text-secondary-light dark:text-text-secondary-dark left-4 top-3 transition-all duration-300 peer-placeholder-shown:top-3 peer-placeholder-shown:text-base peer-focus:-top-2.5 peer-focus:text-sm peer-focus:text-primary dark:peer-focus:text-secondary-light peer-[:not(:placeholder-shown)]:-top-2.5 peer-[:not(:placeholder-shown)]:text-sm bg-background-light dark:bg-surface-dark px-1">
                                Any other feedback?
                            </label>
                        </div>

                        <button type="submit" className="w-full py-3 px-4 rounded-xl bg-gradient-to-r from-secondary to-primary text-white font-bold text-lg shadow-lg hover:shadow-primary/50 dark:hover:shadow-primary/30 transform hover:scale-105 transition-all duration-300 focus:outline-none focus:ring-4 focus:ring-primary/50">
                            Submit Feedback
                        </button>
                    </form>
                ) : (
                    <div className="p-8 flex flex-col items-center justify-center text-center h-96">
                        <div className="w-24 h-24 bg-primary/20 rounded-full flex items-center justify-center mb-6">
                            <CheckIcon className="w-16 h-16 text-primary animate-check"/>
                        </div>
                        <h2 className="text-3xl font-bold text-text-light dark:text-text-dark">Thank You!</h2>
                        <p className="text-text-secondary-light dark:text-text-secondary-dark mt-2">Your feedback helps us improve EcoMed for everyone.</p>
                    </div>
                )}
            </div>
        </div>
    );
};

export default FeedbackScreen;

import React, { useState, useEffect, useCallback } from 'react';
import HomeScreen from './components/HomeScreen';
import ScanScreen from './components/ScanScreen';
import DiagnosisResultScreen from './components/DiagnosisResultScreen';
import HistoryScreen from './components/HistoryScreen';
import FeedbackScreen from './components/FeedbackScreen';
import Header from './components/Header';
import { Diagnosis, HistoryItem } from './types';
import { LeafIcon } from './components/icons';

type View = 'home' | 'scan' | 'result' | 'history' | 'feedback';
type Theme = 'light' | 'dark';

const App: React.FC = () => {
  const [theme, setTheme] = useState<Theme>(() => (localStorage.getItem('theme') as Theme) || 'dark');
  const [currentView, setCurrentView] = useState<View>('home');
  const [diagnosisResult, setDiagnosisResult] = useState<Diagnosis | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [scanOptions, setScanOptions] = useState<{ autoUpload?: boolean }>({});

  useEffect(() => {
    try {
      const savedHistory = localStorage.getItem('plantHistory');
      if (savedHistory) {
        setHistory(JSON.parse(savedHistory));
      }
    } catch (error) {
      console.error("Failed to parse history from localStorage", error);
    }

    // Simulate initial loading
    setTimeout(() => setIsLoading(false), 1000);
  }, []);

  useEffect(() => {
    localStorage.setItem('theme', theme);
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [theme]);

  const handleNavigate = useCallback((view: View, options: { autoUpload?: boolean } = {}) => {
    if (view !== 'scan') {
      setScanOptions({});
    } else {
      setScanOptions(options);
    }
    setCurrentView(view);
  }, []);

  const handleDiagnosisComplete = useCallback((result: Diagnosis) => {
    setDiagnosisResult(result);
    handleNavigate('result');
  }, [handleNavigate]);

  const handleSaveDiagnosis = useCallback(() => {
    if (diagnosisResult) {
      const newHistoryItem: HistoryItem = {
        ...diagnosisResult,
        id: new Date().toISOString(),
        timestamp: new Date().toISOString(),
        image: '', // In a real app, you would store the image data here
      };
      const updatedHistory = [newHistoryItem, ...history];
      setHistory(updatedHistory);
      localStorage.setItem('plantHistory', JSON.stringify(updatedHistory));
      setDiagnosisResult(null);
      handleNavigate('history');
    }
  }, [diagnosisResult, history, handleNavigate]);

  const handleDiscardDiagnosis = useCallback(() => {
    setDiagnosisResult(null);
    handleNavigate('scan');
  }, [handleNavigate]);

  const handleClearHistory = useCallback(() => {
    setHistory([]);
    localStorage.removeItem('plantHistory');
  }, []);

  if (isLoading) {
    return (
      <div className={`flex flex-col items-center justify-center min-h-screen w-full transition-colors duration-500 ${theme === 'light' ? 'bg-background-light' : 'bg-background-dark'}`}>
        <LeafIcon className="w-24 h-24 text-primary animate-pulse" />
        <h1 className="mt-4 text-3xl font-bold text-primary">EcoMed</h1>
        <p className="text-text-secondary-light dark:text-text-secondary-dark">Your personal plant doctor.</p>
      </div>
    );
  }

  const renderContent = () => {
    switch (currentView) {
      case 'scan':
        return <ScanScreen onDiagnosisComplete={handleDiagnosisComplete} onBack={() => handleNavigate('home')} autoUpload={scanOptions.autoUpload} />;
      case 'result':
        return diagnosisResult ? <DiagnosisResultScreen diagnosis={diagnosisResult} onSave={handleSaveDiagnosis} onDiscard={handleDiscardDiagnosis} /> : <HomeScreen onNavigate={handleNavigate} />;
      case 'history':
        return <HistoryScreen history={history} onBack={() => handleNavigate('home')} onClearHistory={handleClearHistory} />;
      case 'feedback':
        return <FeedbackScreen onBack={() => handleNavigate('home')} />;
      case 'home':
      default:
        return <HomeScreen onNavigate={handleNavigate} />;
    }
  };

  return (
    <div className="min-h-screen w-full bg-background-light dark:bg-background-dark text-text-light dark:text-text-dark transition-colors duration-500">
      <Header theme={theme} setTheme={setTheme} onGoHome={() => handleNavigate('home')} />
      <main className="relative p-4 sm:p-6 md:p-8 pt-20 sm:pt-24 max-w-4xl mx-auto">
        {renderContent()}
      </main>
      <footer className="text-center p-4 text-text-secondary-light dark:text-text-secondary-dark text-sm">
        <p>Powered by AI. For educational purposes only.</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { diagnosePlant } from '../services/geminiService';
import { Diagnosis } from '../types';
import { CameraIcon, UploadIcon, BackArrowIcon, SparklesIcon } from './icons';

interface ScanScreenProps {
  onDiagnosisComplete: (result: Diagnosis) => void;
  onBack: () => void;
  autoUpload?: boolean;
}

const ScanScreen: React.FC<ScanScreenProps> = ({ onDiagnosisComplete, onBack, autoUpload }) => {
  const [imageSrc, setImageSrc] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const startCamera = useCallback(async () => {
    try {
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
        const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
        streamRef.current = stream;
        if (videoRef.current) {
            videoRef.current.srcObject = stream;
        }
    } catch (err) {
        console.error("Error accessing camera:", err);
        setError("Could not access the camera. Please check permissions and try again.");
    }
  }, []);

  useEffect(() => {
    startCamera();
    if (autoUpload) {
      fileInputRef.current?.click();
    }
    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
    };
  }, [autoUpload, startCamera]);

  const handleCapture = () => {
    if (videoRef.current) {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth;
      canvas.height = videoRef.current.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg');
        setImageSrc(dataUrl);
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
      }
    }
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setImageSrc(e.target?.result as string);
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleDiagnose = async () => {
    if (!imageSrc) return;
    setIsLoading(true);
    setError(null);
    try {
      const base64Data = imageSrc.split(',')[1];
      const mimeType = imageSrc.match(/data:([a-zA-Z0-9]+\/[a-zA-Z0-9-.+]+).*,.*/)?.[1] || 'image/jpeg';
      const result = await diagnosePlant(base64Data, mimeType);
      onDiagnosisComplete(result);
    } catch (err: any) {
      setError(err.message || 'An unknown error occurred.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleRetake = () => {
      setImageSrc(null);
      setError(null);
      startCamera();
  };

  return (
    <div className="flex flex-col items-center">
        <button onClick={onBack} className="absolute top-4 left-0 flex items-center gap-2 text-text-secondary-light dark:text-text-secondary-dark hover:text-primary dark:hover:text-primary transition-colors">
            <BackArrowIcon className="w-6 h-6" />
            <span>Home</span>
        </button>
      <div className="w-full max-w-lg bg-surface-light dark:bg-surface-dark p-6 rounded-2xl shadow-lg mt-8">
        {isLoading ? (
          <div className="flex flex-col items-center justify-center h-96">
            <SparklesIcon className="w-16 h-16 text-primary animate-spin" />
            <p className="mt-4 text-lg font-semibold">AI is analyzing your plant...</p>
            <p className="text-text-secondary-light dark:text-text-secondary-dark">This might take a moment.</p>
          </div>
        ) : (
          <>
            <div className="relative w-full aspect-square bg-gray-200 dark:bg-gray-700 rounded-lg overflow-hidden mb-4">
              {imageSrc ? (
                <img src={imageSrc} alt="Plant for diagnosis" className="w-full h-full object-cover" />
              ) : (
                <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover"></video>
              )}
            </div>

            {error && <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded-lg relative mb-4" role="alert">{error}</div>}

            {imageSrc ? (
              <div className="grid grid-cols-2 gap-4">
                <button onClick={handleRetake} className="w-full py-3 px-4 rounded-lg bg-gray-200 dark:bg-gray-600 hover:bg-gray-300 dark:hover:bg-gray-500 font-semibold transition-colors">
                  Retake Photo
                </button>
                <button onClick={handleDiagnose} className="w-full flex items-center justify-center gap-2 py-3 px-4 rounded-lg bg-primary hover:bg-primary-dark text-white font-bold transition-colors">
                  <SparklesIcon className="w-5 h-5"/>
                  Diagnose
                </button>
              </div>
            ) : (
              <div className="grid grid-cols-2 gap-4">
                <button onClick={handleCapture} className="w-full flex items-center justify-center gap-2 py-3 px-4 rounded-lg bg-primary hover:bg-primary-dark text-white font-bold transition-colors">
                  <CameraIcon className="w-5 h-5"/>
                  Capture
                </button>
                <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center justify-center gap-2 py-3 px-4 rounded-lg bg-secondary hover:bg-secondary-dark dark:text-gray-900 font-bold transition-colors">
                  <UploadIcon className="w-5 h-5"/>
                  Upload
                </button>
                <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*" className="hidden" />
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
};

export default ScanScreen;

