import React, { useState, useEffect } from 'react';
import { Diagnosis } from '../types';
import { SparklesIcon, LeafIcon, ChevronDownIcon } from './icons';

interface DiagnosisResultScreenProps {
  diagnosis: Diagnosis;
  onSave: () => void;
  onDiscard: () => void;
}

// Sub-component: Animated Circular Progress for confidence score
const CircularProgress: React.FC<{ progress: number; color: string }> = ({ progress, color }) => {
    const [displayProgress, setDisplayProgress] = useState(0);
    const size = 120;
    const strokeWidth = 10;
    const radius = (size - strokeWidth) / 2;
    const circumference = 2 * Math.PI * radius;
    const offset = circumference - (displayProgress / 100) * circumference;

    useEffect(() => {
        const timer = setTimeout(() => setDisplayProgress(progress), 100);
        return () => clearTimeout(timer);
    }, [progress]);

    return (
        <div className="relative" style={{ width: size, height: size }}>
            <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
                <circle className="stroke-slate-200 dark:stroke-slate-700" fill="transparent" strokeWidth={strokeWidth} r={radius} cx={size / 2} cy={size / 2} />
                <circle
                    className="transition-all duration-1000 ease-out"
                    stroke={color}
                    fill="transparent"
                    strokeWidth={strokeWidth}
                    strokeDasharray={circumference}
                    strokeDashoffset={offset}
                    strokeLinecap="round"
                    r={radius}
                    cx={size / 2}
                    cy={size / 2}
                    transform={`rotate(-90 ${size / 2} ${size / 2})`}
                />
            </svg>
            <div className="absolute inset-0 flex flex-col items-center justify-center">
                <span className="text-3xl font-bold" style={{ color }}>{Math.round(displayProgress)}%</span>
                <span className="text-sm text-text-secondary-light dark:text-text-secondary-dark">Confidence</span>
            </div>
        </div>
    );
};

// Sub-component: Accordion for treatment plan
const Accordion: React.FC<{ title: string; children: React.ReactNode; icon: React.ReactNode; }> = ({ title, children, icon }) => {
    const [isOpen, setIsOpen] = useState(false);
    return (
        <div className="border-t border-slate-200 dark:border-slate-700">
            <button onClick={() => setIsOpen(!isOpen)} className="flex justify-between items-center w-full py-4 text-left font-semibold text-lg hover:bg-slate-50 dark:hover:bg-slate-700/50 px-2 rounded-md transition-colors">
                <div className="flex items-center gap-3">
                    {icon}
                    <span>{title}</span>
                </div>
                <ChevronDownIcon className={`w-6 h-6 transition-transform duration-300 ${isOpen ? 'rotate-180' : ''}`} />
            </button>
            <div className={`grid overflow-hidden transition-all duration-300 ease-in-out ${isOpen ? 'grid-rows-[1fr] opacity-100' : 'grid-rows-[0fr] opacity-0'}`}>
                <div className="overflow-hidden">
                    <div className="pb-4 px-2">{children}</div>
                </div>
            </div>
        </div>
    );
}

const DiagnosisResultScreen: React.FC<DiagnosisResultScreenProps> = ({ diagnosis, onSave, onDiscard }) => {
    const confidenceValue = Math.round(diagnosis.confidence * 100);
    const confidenceColor = confidenceValue > 75 ? '#22c55e' : confidenceValue > 50 ? '#f59e0b' : '#ef4444';

    const renderList = (items: string[]) => {
        if (!items || items.length === 0) return <p className="text-text-secondary-light dark:text-text-secondary-dark italic">No specific recommendations provided.</p>;
        return (
            <ul className="list-disc list-inside space-y-2 text-text-secondary-light dark:text-text-secondary-dark">
                {items.map((item, index) => <li key={index}>{item}</li>)}
            </ul>
        );
    };

    return (
        <div className="space-y-6">
            <div className="p-6 bg-gradient-to-br from-surface-light to-slate-100 dark:from-surface-dark dark:to-slate-900/50 rounded-2xl shadow-lg flex flex-col md:flex-row items-center gap-6 animate-fade-in">
                <div className="flex-grow text-center md:text-left">
                    <h2 className="text-4xl font-bold text-primary">{diagnosis.plantName}</h2>
                    <div className={`mt-2 text-2xl font-semibold ${diagnosis.isHealthy ? 'text-green-500' : 'text-orange-500'}`}>
                        {diagnosis.isHealthy ? 'Healthy' : diagnosis.disease}
                    </div>
                </div>
                {!diagnosis.isHealthy && (
                    <div className="flex-shrink-0">
                        <CircularProgress progress={confidenceValue} color={confidenceColor} />
                    </div>
                )}
            </div>

            <InfoCard title="AI Diagnosis Summary" delay={100}>
                <p className="text-text-secondary-light dark:text-text-secondary-dark">{diagnosis.description}</p>
            </InfoCard>

            {!diagnosis.isHealthy && (
                <>
                    <InfoCard title="Symptoms" delay={200}>
                        {renderList(diagnosis.symptoms)}
                    </InfoCard>

                    <InfoCard title="Treatment Plan" delay={300}>
                        <Accordion title="Organic Solutions" icon={<LeafIcon className="w-6 h-6 text-green-500" />}>
                            {renderList(diagnosis.treatments.organic)}
                        </Accordion>
                        <Accordion title="Chemical Solutions" icon={<SparklesIcon className="w-6 h-6 text-blue-500" />}>
                            {renderList(diagnosis.treatments.chemical)}
                        </Accordion>
                    </InfoCard>

                    <InfoCard title="Prevention Tips" delay={400}>
                        {renderList(diagnosis.prevention)}
                    </InfoCard>
                </>
            )}

            <div className="sticky bottom-4 grid grid-cols-2 gap-4 p-2 bg-background-light/80 dark:bg-background-dark/80 backdrop-blur-lg rounded-2xl border border-slate-200/80 dark:border-slate-700/80 shadow-lg animate-fade-in" style={{animationDelay: '500ms'}}>
                <button onClick={onDiscard} className="w-full py-3 px-4 rounded-lg bg-gray-200 dark:bg-gray-600 hover:bg-gray-300 dark:hover:bg-gray-500 font-semibold transition-colors">
                    Scan Another
                </button>
                <button onClick={onSave} className="w-full flex items-center justify-center gap-2 py-3 px-4 rounded-lg bg-primary hover:bg-primary-dark text-white font-bold transition-colors">
                    <LeafIcon className="w-5 h-5"/>
                    Save to My Garden
                </button>
            </div>
        </div>
    );
};

interface InfoCardProps {
    title: string;
    children: React.ReactNode;
    delay?: number;
}

const InfoCard: React.FC<InfoCardProps> = ({ title, children, delay = 0 }) => (
    <div className="p-6 bg-surface-light dark:bg-surface-dark rounded-2xl shadow-lg animate-fade-in" style={{ animationDelay: `${delay}ms`}}>
