import React, { useState, useRef, useEffect, useCallback } from 'react';
import { diagnosePlant } from '../services/geminiService';
import { Diagnosis } from '../types';
import { CameraIcon, UploadIcon, BackArrowIcon, SparklesIcon } from './icons';

interface ScanScreenProps {
  onDiagnosisComplete: (result: Diagnosis) => void;
  onBack: () => void;
  autoUpload?: boolean;
}

const ScanScreen: React.FC<ScanScreenProps> = ({ onDiagnosisComplete, onBack, autoUpload }) => {
  const [imageSrc, setImageSrc] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const startCamera = useCallback(async () => {
    try {
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
        const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
        streamRef.current = stream;
        if (videoRef.current) {
            videoRef.current.srcObject = stream;
        }
    } catch (err) {
        console.error("Error accessing camera:", err);
        setError("Could not access the camera. Please check permissions and try again.");
    }
  }, []);

  useEffect(() => {
    startCamera();
    if (autoUpload) {
      fileInputRef.current?.click();
    }
    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
    };
  }, [autoUpload, startCamera]);

  const handleCapture = () => {
    if (videoRef.current) {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth;
      canvas.height = videoRef.current.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg');
        setImageSrc(dataUrl);
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
      }
    }
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setImageSrc(e.target?.result as string);
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleDiagnose = async () => {
    if (!imageSrc) return;
    setIsLoading(true);
    setError(null);
    try {
      const base64Data = imageSrc.split(',')[1];
      const mimeType = imageSrc.match(/data:([a-zA-Z0-9]+\/[a-zA-Z0-9-.+]+).*,.*/)?.[1] || 'image/jpeg';
      const result = await diagnosePlant(base64Data, mimeType);
      onDiagnosisComplete(result);
    } catch (err: any) {
      setError(err.message || 'An unknown error occurred.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleRetake = () => {
      setImageSrc(null);
      setError(null);
      startCamera();
  };

  return (
    <div className="animate-fade-in">
        <div className="flex items-center mb-6">
            <button onClick={onBack} className="flex items-center gap-2 text-brand-text-muted hover:text-brand-primary transition-colors">
                <BackArrowIcon className="w-6 h-6" />
                <span className="text-lg">Home</span>
            </button>
        </div>

      <div className="w-full max-w-lg mx-auto bg-brand-surface p-6 rounded-2xl shadow-lg">
        <h2 className="text-3xl font-bold text-center text-brand-primary mb-6">Scan Your Plant</h2>
        {isLoading ? (
          <div className="flex flex-col items-center justify-center h-96">
            <SparklesIcon className="w-16 h-16 text-brand-primary animate-spin" />
            <p className="mt-4 text-lg font-semibold">AI is analyzing your plant...</p>
            <p className="text-brand-text-muted">This might take a moment.</p>
          </div>
        ) : (
          <>
            <div className="relative w-full aspect-square bg-brand-dark rounded-lg overflow-hidden mb-4">
              {imageSrc ? (
                <img src={imageSrc} alt="Plant for diagnosis" className="w-full h-full object-cover" />
              ) : (
                <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover"></video>
              )}
            </div>

            {error && <div className="bg-red-500/20 border border-red-500 text-red-300 px-4 py-3 rounded-lg relative mb-4" role="alert">{error}</div>}

            {imageSrc ? (
              <div className="grid grid-cols-2 gap-4">
                <button onClick={handleRetake} className="w-full py-3 px-4 rounded-lg bg-brand-dark hover:bg-opacity-80 font-semibold transition-colors">
                  Retake Photo
                </button>
                <button onClick={handleDiagnose} className="w-full flex items-center justify-center gap-2 py-3 px-4 rounded-lg bg-brand-primary hover:opacity-90 text-brand-dark font-bold transition-colors">
                  <SparklesIcon className="w-5 h-5"/>
                  Diagnose
                </button>
              </div>
            ) : (
              <div className="grid grid-cols-2 gap-4">
                <button onClick={handleCapture} className="w-full flex items-center justify-center gap-2 py-3 px-4 rounded-lg bg-brand-primary hover:opacity-90 text-brand-dark font-bold transition-colors">
                  <CameraIcon className="w-5 h-5 text-brand-dark"/>
                  Capture
                </button>
                <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center justify-center gap-2 py-3 px-4 rounded-lg bg-brand-dark hover:bg-opacity-80 text-brand-text font-bold transition-colors">
                  <UploadIcon className="w-5 h-5"/>
                  Upload
                </button>
                <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*" className="hidden" />
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
};

export default ScanScreen;

import React, { useState, useEffect } from 'react';
