            <button onClick={() => setIsOpen(!isOpen)} className="flex justify-between items-center w-full py-4 text-left font-semibold text-lg hover:bg-brand-text/5 px-2 rounded-md transition-colors">
                <div className="flex items-center gap-3">
                    {icon}
                    <span>{title}</span>
                </div>
                <ChevronDownIcon className={`w-6 h-6 transition-transform duration-300 ${isOpen ? 'rotate-180' : ''}`} />
            </button>
            <div className={`grid overflow-hidden transition-all duration-300 ease-in-out ${isOpen ? 'grid-rows-[1fr] opacity-100' : 'grid-rows-[0fr] opacity-0'}`}>
                <div className="overflow-hidden">
                    <div className="pb-4 px-2">{children}</div>
                </div>
            </div>
        </div>
    );
}

const DiagnosisResultScreen: React.FC<DiagnosisResultScreenProps> = ({ diagnosis, onSave, onDiscard }) => {
    const confidenceValue = Math.round(diagnosis.confidence * 100);
    const confidenceColor = confidenceValue > 75 ? '#1EEA92' : confidenceValue > 50 ? '#f59e0b' : '#ef4444';

    const renderList = (items: string[]) => {
        if (!items || items.length === 0) return <p className="text-brand-text-muted italic">No specific recommendations provided.</p>;
        return (
            <ul className="list-disc list-inside space-y-2 text-brand-text-muted">
                {items.map((item, index) => <li key={index}>{item}</li>)}
            </ul>
        );
    };

    return (
        <div className="space-y-6 animate-fade-in">
            <div className="p-6 bg-brand-surface rounded-2xl shadow-lg flex flex-col md:flex-row items-center gap-6">
                <div className="flex-grow text-center md:text-left">
                    <h2 className="text-4xl font-bold text-brand-primary">{diagnosis.plantName}</h2>
                    <div className={`mt-2 text-2xl font-semibold ${diagnosis.isHealthy ? 'text-green-500' : 'text-orange-500'}`}>
                        {diagnosis.isHealthy ? 'Healthy' : diagnosis.disease}
                    </div>
                </div>
                {!diagnosis.isHealthy && (
                    <div className="flex-shrink-0">
                        <CircularProgress progress={confidenceValue} color={confidenceColor} />
                    </div>
                )}
            </div>

            <InfoCard title="AI Diagnosis Summary" delay={100}>
                <p className="text-brand-text-muted">{diagnosis.description}</p>
            </InfoCard>

            {!diagnosis.isHealthy && (
                <>
                    <InfoCard title="Symptoms" delay={200}>
                        {renderList(diagnosis.symptoms)}
                    </InfoCard>

                    <InfoCard title="Treatment Plan" delay={300}>
                        <Accordion title="Organic Solutions" icon={<LeafIcon className="w-6 h-6 text-green-500" />}>
                            {renderList(diagnosis.treatments.organic)}
                        </Accordion>
                        <Accordion title="Chemical Solutions" icon={<SparklesIcon className="w-6 h-6 text-blue-500" />}>
                            {renderList(diagnosis.treatments.chemical)}
                        </Accordion>
                    </InfoCard>

                    <InfoCard title="Prevention Tips" delay={400}>
                        {renderList(diagnosis.prevention)}
                    </InfoCard>
                </>
            )}

            <div className="sticky bottom-4 grid grid-cols-2 gap-4 p-2 bg-brand-dark/80 backdrop-blur-lg rounded-2xl border border-brand-text/10 shadow-lg animate-fade-in" style={{animationDelay: '500ms'}}>
                <button onClick={onDiscard} className="w-full py-3 px-4 rounded-lg bg-brand-surface hover:bg-opacity-80 font-semibold transition-colors">
                    Scan Another
                </button>
                <button onClick={onSave} className="w-full flex items-center justify-center gap-2 py-3 px-4 rounded-lg bg-brand-primary hover:opacity-90 text-brand-dark font-bold transition-colors">
                    <LeafIcon className="w-5 h-5"/>
                    Save to My Garden
                </button>
            </div>
        </div>
    );
};

