import React, { useState, useEffect, useCallback } from 'react';
import HomeScreen from './components/HomeScreen';
import ScanScreen from './components/ScanScreen';
import DiagnosisResultScreen from './components/DiagnosisResultScreen';
import HistoryScreen from './components/HistoryScreen';
import FeedbackScreen from './components/FeedbackScreen';
import { Diagnosis, HistoryItem } from './types';
import { LeafIcon } from './components/icons';

type View = 'home' | 'scan' | 'result' | 'history' | 'feedback';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('home');
  const [diagnosisResult, setDiagnosisResult] = useState<Diagnosis | null>(null);
  const [diagnosisImage, setDiagnosisImage] = useState<string | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [scanOptions, setScanOptions] = useState<{ autoUpload?: boolean }>({});

  useEffect(() => {
    try {
      const savedHistory = localStorage.getItem('plantHistory');
      if (savedHistory) {
        setHistory(JSON.parse(savedHistory));
      }
    } catch (error) {
      console.error("Failed to parse history from localStorage", error);
    }

    // Simulate initial loading
    setTimeout(() => setIsLoading(false), 1000);
  }, []);

  const handleNavigate = useCallback((view: View, options: { autoUpload?: boolean } = {}) => {
    if (view !== 'scan') {
      setScanOptions({});
    } else {
      setScanOptions(options);
    }
    setCurrentView(view);
  }, []);

  const handleDiagnosisComplete = useCallback((result: Diagnosis, imageSrc: string) => {
    setDiagnosisResult(result);
    setDiagnosisImage(imageSrc);
    handleNavigate('result');
  }, [handleNavigate]);

  const handleSaveDiagnosis = useCallback(() => {
    if (diagnosisResult && diagnosisImage) {
      const newHistoryItem: HistoryItem = {
        ...diagnosisResult,
        id: new Date().toISOString(),
        timestamp: new Date().toISOString(),
        image: diagnosisImage,
      };
      const updatedHistory = [newHistoryItem, ...history];
      setHistory(updatedHistory);
      localStorage.setItem('plantHistory', JSON.stringify(updatedHistory));
      setDiagnosisResult(null);
      setDiagnosisImage(null);
      handleNavigate('history');
    }
  }, [diagnosisResult, diagnosisImage, history, handleNavigate]);

  const handleDiscardDiagnosis = useCallback(() => {
    setDiagnosisResult(null);
    setDiagnosisImage(null);
    handleNavigate('scan');
  }, [handleNavigate]);

  const handleClearHistory = useCallback(() => {
    setHistory([]);
    localStorage.removeItem('plantHistory');
  }, []);

  if (isLoading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen w-full bg-brand-dark">
        <LeafIcon className="w-24 h-24 text-brand-primary animate-pulse" />
        <h1 className="mt-4 text-3xl font-bold text-brand-primary">Botanist</h1>
        <p className="text-brand-text-muted">Your personal plant doctor.</p>
      </div>
    );
  }

  const renderContent = () => {
    switch (currentView) {
      case 'scan':
        return <ScanScreen onDiagnosisComplete={handleDiagnosisComplete} onBack={() => handleNavigate('home')} autoUpload={scanOptions.autoUpload} />;
      case 'result':
        return diagnosisResult ? <DiagnosisResultScreen diagnosis={diagnosisResult} imageSrc={diagnosisImage} onSave={handleSaveDiagnosis} onDiscard={handleDiscardDiagnosis} /> : <HomeScreen onNavigate={handleNavigate} />;
      case 'history':
        return <HistoryScreen history={history} onBack={() => handleNavigate('home')} onClearHistory={handleClearHistory} />;
      case 'feedback':
        return <FeedbackScreen onBack={() => handleNavigate('home')} />;
      case 'home':
      default:
        return <HomeScreen onNavigate={handleNavigate} />;
    }
  };

  return (
    <div className="min-h-screen w-full bg-brand-dark text-brand-text">
      <main className="relative p-4 sm:p-6 md:p-8 max-w-6xl mx-auto">
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { diagnosePlant } from '../services/geminiService';
import { Diagnosis } from '../types';
import { CameraIcon, UploadIcon, BackArrowIcon, SparklesIcon } from './icons';

interface ScanScreenProps {
  onDiagnosisComplete: (result: Diagnosis, imageSrc: string) => void;
  onBack: () => void;
  autoUpload?: boolean;
}

const ScanScreen: React.FC<ScanScreenProps> = ({ onDiagnosisComplete, onBack, autoUpload }) => {
  const [imageSrc, setImageSrc] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const startCamera = useCallback(async () => {
    try {
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
        const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
        streamRef.current = stream;
        if (videoRef.current) {
            videoRef.current.srcObject = stream;
        }
    } catch (err) {
        console.error("Error accessing camera:", err);
        setError("Could not access the camera. Please check permissions and try again.");
    }
  }, []);

  useEffect(() => {
    startCamera();
    if (autoUpload) {
      fileInputRef.current?.click();
    }
    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
    };
  }, [autoUpload, startCamera]);

  const handleCapture = () => {
    if (videoRef.current) {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth;
      canvas.height = videoRef.current.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg');
        setImageSrc(dataUrl);
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
      }
    }
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setImageSrc(e.target?.result as string);
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleDiagnose = async () => {
    if (!imageSrc) return;
    setIsLoading(true);
    setError(null);
    try {
      const base64Data = imageSrc.split(',')[1];
      const mimeType = imageSrc.match(/data:([a-zA-Z0-9]+\/[a-zA-Z0-9-.+]+).*,.*/)?.[1] || 'image/jpeg';
      const result = await diagnosePlant(base64Data, mimeType);
      onDiagnosisComplete(result, imageSrc);
    } catch (err: any) {
      setError(err.message || 'An unknown error occurred.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleRetake = () => {
      setImageSrc(null);
      setError(null);
      startCamera();
  };

  return (
    <div className="animate-fade-in">
        <div className="flex items-center mb-6">
            <button onClick={onBack} className="flex items-center gap-2 text-brand-text-muted hover:text-brand-primary transition-colors">
                <BackArrowIcon className="w-6 h-6" />
                <span className="text-lg">Home</span>
            </button>
        </div>

      <div className="w-full max-w-lg mx-auto bg-brand-surface p-6 rounded-2xl shadow-lg">
        <h2 className="text-3xl font-bold text-center text-brand-primary mb-6">Scan Your Plant</h2>
        {isLoading ? (
          <div className="flex flex-col items-center justify-center h-96">
            <SparklesIcon className="w-16 h-16 text-brand-primary animate-spin" />
