interface FeedbackScreenProps {
    onBack: () => void;
}

const EMOJI_REACTIONS = [
    { name: 'disappointed', emoji: '😞' },
    { name: 'neutral', emoji: '😐' },
    { name: 'satisfied', emoji: '😊' },
    { name: 'happy', emoji: '😄' },
    { name: 'amazed', emoji: '🤩' },
];

const FeedbackScreen: React.FC<FeedbackScreenProps> = ({ onBack }) => {
    const [step, setStep] = useState(1);
    const [rating, setRating] = useState(0);
    const [hoverRating, setHoverRating] = useState(0);
    const [reaction, setReaction] = useState<string | null>(null);
    const [comment, setComment] = useState('');

    const progress = useMemo(() => {
        const completed = [rating > 0, reaction !== null, comment.trim().length > 5].filter(Boolean).length;
        return (completed / 3) * 100;
    }, [rating, reaction, comment]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setStep(2);
    };

    useEffect(() => {
        if (step === 2) {
            const timer = setTimeout(() => {
                onBack();
            }, 3000);
            return () => clearTimeout(timer);
        }
    }, [step, onBack]);

    return (
        <div className="relative z-10 animate-fade-in pt-10">
            <button onClick={onBack} className="absolute top-4 left-0 flex items-center gap-2 text-brand-text-muted hover:text-brand-primary transition-colors z-20">
                <BackArrowIcon className="w-6 h-6" />
                <span>Home</span>
            </button>

            <div className="relative w-full max-w-md mx-auto glass-card rounded-3xl shadow-2xl overflow-hidden">
                <div className="w-full h-2 bg-brand-surface">
                    <div
                        className="h-full bg-gradient-to-r from-brand-secondary to-brand-primary transition-all duration-500 ease-out"
                        style={{ width: `${progress}%` }}
                    ></div>
                </div>

                {step === 1 ? (
                    <form onSubmit={handleSubmit} className="p-8 space-y-8">
                        <div>
                            <h2 className="text-3xl font-bold text-center text-brand-text">Share Your Feedback</h2>
                            <p className="text-center text-brand-text-muted mt-1">How was your experience?</p>
                        </div>

                        <div className="space-y-4">
                            <label className="font-semibold text-brand-text">How would you describe it?</label>
                            <div className="flex justify-between">
                                {EMOJI_REACTIONS.map(({name, emoji}) => (
                                    <button 
                                        key={name} 
                                        type="button"
                                        onClick={() => setReaction(name)}
                                        className={`p-2 rounded-full text-3xl transition-all duration-200 ${reaction === name ? 'bg-brand-primary/20 scale-125' : 'hover:scale-110 hover:bg-brand-surface'}`}
                                    >
                                        {emoji}
                                    </button>
                                ))}
                            </div>
                        </div>

                        <div className="space-y-4">
                             <label className="font-semibold text-brand-text">Rate our app</label>
                             <div className="flex justify-center items-center space-x-2" onMouseLeave={() => setHoverRating(0)}>
                                {[1, 2, 3, 4, 5].map((star) => (
                                    <StarIcon 
                                        key={star}
                                        className={`w-10 h-10 cursor-pointer transition-all duration-150 ${ (hoverRating || rating) >= star ? 'text-yellow-400 fill-yellow-400' : 'text-brand-text-muted/50' }`}
                                        onClick={() => setRating(star)}
                                        onMouseEnter={() => setHoverRating(star)}
                                    />
                                ))}
                             </div>
                        </div>

                        <div className="relative">
                            <textarea
                                id="comment"
                                value={comment}
                                onChange={(e) => setComment(e.target.value)}
                                className="peer block w-full h-28 px-4 py-3 bg-brand-surface rounded-lg border-2 border-transparent focus:border-brand-primary focus:outline-none focus:ring-0 transition-colors text-brand-text"
                                placeholder=" "
                            ></textarea>
                            <label htmlFor="comment" className="absolute text-brand-text-muted left-4 top-3 transition-all duration-300 peer-placeholder-shown:top-3 peer-placeholder-shown:text-base peer-focus:-top-2.5 peer-focus:text-sm peer-focus:text-brand-primary px-1 bg-brand-surface">
                                Any other feedback?
                            </label>
                        </div>

                        <button type="submit" className="w-full py-3 px-4 rounded-xl bg-gradient-to-r from-brand-secondary to-brand-primary text-brand-dark font-bold text-lg shadow-lg hover:shadow-brand-primary/30 transform hover:scale-105 transition-all duration-300 focus:outline-none focus:ring-4 focus:ring-brand-primary/50">
                            Submit Feedback
                        </button>
                    </form>
                ) : (
                    <div className="relative p-8 flex flex-col items-center justify-center text-center h-[28rem]">
                        <div className="relative z-10">
                            <div className="w-24 h-24 bg-brand-primary/20 rounded-full flex items-center justify-center mb-6 mx-auto">
                                <CheckIcon className="w-16 h-16 text-brand-primary " style={{strokeDasharray: 50, strokeDashoffset: 50, animation: 'draw-check 0.5s cubic-bezier(.77,0,.18,1) forwards'}}/>
                            </div>
                            <h2 className="text-3xl font-bold text-brand-text">Thank You!</h2>
                            <p className="text-brand-text-muted mt-2">Your feedback helps us improve for everyone.</p>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

