const ConfidenceGauge: React.FC<{ progress: number; color: string }> = ({ progress, color }) => {
    const [displayProgress, setDisplayProgress] = useState(0);
    const strokeWidth = 12;
    const size = 140;
    const radius = (size - strokeWidth) / 2;
    const circumference = Math.PI * radius; // Half circle

    useEffect(() => {
        const timer = setTimeout(() => setDisplayProgress(progress), 100);
        return () => clearTimeout(timer);
    }, [progress]);

    const offset = circumference - (displayProgress / 100) * circumference;

    return (
        <div className="relative animate-scale-in" style={{ width: size, height: size / 2 + strokeWidth }}>
            <svg width={size} height={size/2 + strokeWidth} viewBox={`0 0 ${size} ${size/2 + strokeWidth}`} className="overflow-visible">
                <path d={`M ${strokeWidth/2},${size/2} a ${radius},${radius} 0 0,1 ${radius*2},0`}
                    className="stroke-brand-surface" fill="none" strokeWidth={strokeWidth} strokeLinecap="round" />
                <path d={`M ${strokeWidth/2},${size/2} a ${radius},${radius} 0 0,1 ${radius*2},0`}
                    stroke={color} fill="none" strokeWidth={strokeWidth} strokeLinecap="round"
                    strokeDasharray={circumference} strokeDashoffset={offset}
                    className="transition-all duration-1000 ease-out" />
            </svg>
            <div className="absolute bottom-0 left-1/2 -translate-x-1/2 text-center">
                <span className="text-4xl font-display font-bold transition-all duration-500" style={{ color }}>{Math.round(displayProgress)}%</span>
                <span className="block text-xs text-brand-text-muted uppercase tracking-widest">Confidence</span>
            </div>
        </div>
    );
};

