        try {
            const url = await generateArtisticVision(diagnosis.plantName, diagnosis.disease || 'healthy', diagnosis.isHealthy);
            setArtisticImage(url);
        } catch (err: any) {
            setArtError("Could not generate illustration. Please try again.");
            showFeedback("AI Art generation failed.", "error");
