}

const steps = [
  {
    title: "Welcome to EcoMed",
    description: "Your AI companion for professional-grade plant pathology. Let's get you ready to heal your garden.",
    icon: <LeafIcon className="w-16 h-16 text-brand-primary" />,
  },
  {
    title: "Instant Diagnosis",
