    icon: <CameraIcon className="w-16 h-16 text-brand-secondary" />,
  },
  {
    title: "Prescriptive Care",
    description: "Receive complete treatment plans including organic solutions and prevention tips.",
    icon: <SparklesIcon className="w-16 h-16 text-emerald-400" />,
  },
  {
    title: "Garden Archive",
    description: "All your scans are saved automatically. Track progress and watch your garden thrive.",
    icon: <DatabaseIcon className="w-16 h-16 text-brand-primary" />,
  }
];

const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [currentStep, setCurrentStep] = useState(0);

  const handleNext = () => {
    if (currentStep < steps.length - 1) {
      setCurrentStep(currentStep + 1);
    } else {
      onComplete();
    }
  };

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-brand-dark/90 backdrop-blur-xl animate-fade-in">
        <button onClick={onComplete} className="absolute top-6 right-6 w-10 h-10 glass-card rounded-full flex items-center justify-center hover:border-white/20 transition-colors">
            <XIcon className="w-6 h-6 text-brand-text-muted" />
        </button>

      <div className="relative w-full max-w-sm glass-card rounded-3xl overflow-hidden shadow-2xl animate-scale-in border border-white/10">
        <div className="p-8 flex flex-col items-center text-center">
            <div className="h-48 flex items-center justify-center">
              {steps.map((step, index) => (
                  <div key={index} className={`transition-all duration-500 absolute ${index === currentStep ? 'opacity-100 scale-100' : 'opacity-0 scale-90'}`}>
                    <div className="animate-float">
                        <div className="relative p-6 bg-brand-dark/50 rounded-3xl border border-white/10 shadow-2xl">
                            {step.icon}
                        </div>
                        <div className="absolute inset-0 -z-10 bg-brand-primary/10 rounded-full blur-2xl"></div>
                    </div>
                  </div>
              ))}
            </div>

          <h2 className="font-display text-3xl font-black text-white mb-4 tracking-tight leading-none h-20">
            {steps[currentStep].title}
          </h2>

          <p className="text-brand-text-muted text-lg leading-relaxed font-medium mb-8 h-24">
            {steps[currentStep].description}
          </p>

          <div className="flex items-center gap-2 mb-8">
            {steps.map((_, i) => (
              <div 
                key={i} 
                className={`h-1.5 rounded-full transition-all duration-300 ${i === currentStep ? 'w-6 bg-brand-primary' : 'w-1.5 bg-white/20'}`}
              />
            ))}
          </div>

          <button
            onClick={handleNext}
            className="w-full py-4 bg-brand-primary text-brand-dark font-black text-lg rounded-xl shadow-lg hover:opacity-90 transition-all flex items-center justify-center gap-2"
          >
            {currentStep === steps.length - 1 ? (
              <>
                <CheckIcon className="w-6 h-6" /> Get Started
              </>
            ) : ( "Continue" )}
          </button>
        </div>
      </div>
    </div>
  );
};

