import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { Diagnosis } from '../types';

const API_KEY = process.env.API_KEY;

if (!API_KEY) {
  throw new Error("API_KEY environment variable is not set");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

const diagnosisSchema = {
    type: Type.OBJECT,
    properties: {
        plantName: { type: Type.STRING, description: "The common name of the plant. If unsure, state 'Unknown Plant'." },
        isHealthy: { type: Type.BOOLEAN, description: "True if the plant appears healthy, false otherwise." },
        disease: { type: Type.STRING, description: "The common name of the disease or pest. Null if healthy." },
        confidence: { type: Type.NUMBER, description: "Confidence in the diagnosis, from 0.0 to 1.0." },
        description: { type: Type.STRING, description: "A brief, easy-to-understand summary of the diagnosis for a non-expert." },
        symptoms: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            description: "A list of key symptoms observed or typical for the diagnosed issue."
        },
        treatments: {
            type: Type.OBJECT,
            properties: {
                organic: {
                    type: Type.ARRAY,
                    items: { type: Type.STRING },
                    description: "A list of organic/natural treatment suggestions."
                },
                chemical: {
                    type: Type.ARRAY,
                    items: { type: Type.STRING },
                    description: "A list of chemical treatment suggestions."
                },
            },
        },
        prevention: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            description: "A list of tips to prevent this issue in the future."
        },
    },
    required: ["plantName", "isHealthy", "disease", "confidence", "description", "symptoms", "treatments", "prevention"],
};

const fileToGenerativePart = (base64: string, mimeType: string) => {
  return {
    inlineData: {
      data: base64,
      mimeType
    },
  };
};

export const diagnosePlant = async (base64Image: string, mimeType: string): Promise<Diagnosis> => {
  try {
    const imagePart = fileToGenerativePart(base64Image, mimeType);

    const prompt = `You are an expert botanist and plant pathologist named EcoMed AI. Your task is to analyze the provided image of a plant.

Based on the image, provide a diagnosis. Respond with only a valid JSON object that strictly adheres to the defined schema. Do not include any text, markdown formatting, or explanations outside of the JSON object.`;

    const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [{ parts: [imagePart, { text: prompt }] }],
        config: {
            responseMimeType: "application/json",
            responseSchema: diagnosisSchema,
        },
    });

    const text = response.text;
    if (!text) {
        throw new Error("API returned an empty response.");
    }

    const parsedJson = JSON.parse(text);
    return parsedJson as Diagnosis;

  } catch (error) {
    console.error("Error diagnosing plant:", error);
    throw new Error("Failed to get a diagnosis from the AI. Please try again.");
  }
};

export const generateArtisticVision = async (plantName: string, diagnosis: string, isHealthy: boolean): Promise<string> => {
    try {
        const prompt = `Subject: A single, perfect specimen of a ${plantName} plant.
        Condition: ${isHealthy ? 'The plant is depicted in a state of perfect health, vibrant and flourishing.' : `The plant is artistically showing the subtle, early-stage signs of ${diagnosis}.`}
        Style: Ultra-realistic, cinematic macro photography. Shot on a Hasselblad X2D 100C.
        Lighting: Soft, diffused morning light creating a gentle glow and long, soft shadows. Dramatic, cinematic lighting.
        Composition: Asymmetrical, rule of thirds. The plant is the clear focal point.
        Background: Deep, dark, moody, out-of-focus natural foliage, creating a beautiful soft bokeh.
        Details: Hyper-detailed, capture the microscopic textures of the leaves, tiny water droplets, and fine hairs on the stem. 8k resolution, photorealistic.
        Color Palette: Rich, natural greens, deep shadows, and subtle highlights.`;

        const response: GenerateContentResponse = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: [{
                parts: [{ text: prompt }]
            }],
            config: {
                imageConfig: {
                    aspectRatio: "1:1"
                }
            }
        });

        const imagePart = response.candidates?.[0]?.content?.parts.find(part => part.inlineData);
        if (imagePart?.inlineData) {
            return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
        }

        throw new Error("No image data found in response");
    } catch (error) {
        console.error("Error generating artistic vision:", error);
        throw new Error("Failed to generate artistic vision.");
    }
};

import React, { useState, useEffect, useCallback, useTransition } from 'react';
import Header from './components/Header';
import ScanScreen from './components/ScanScreen';
import DiagnosisResultScreen from './components/DiagnosisResultScreen';
import HistoryScreen from './components/HistoryScreen';
import FeedbackScreen from './components/FeedbackScreen';
import Onboarding from './components/Onboarding';
import { Diagnosis, HistoryItem, View, Theme } from './types';
import { LeafIcon } from './components/icons';

const App: React.FC = () => {
  const [theme, setTheme] = useState<Theme>('dark');
  const [currentView, setCurrentView] = useState<View>('scan');
  const [diagnosisResult, setDiagnosisResult] = useState<Diagnosis | null>(null);
  const [diagnosisImage, setDiagnosisImage] = useState<string | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [scanOptions, setScanOptions] = useState<{ autoUpload?: boolean }>({});
  const [prefilledFeedback, setPrefilledFeedback] = useState<string>('');
  const [isNavigating, startNavigation] = useTransition();
  const [animationClass, setAnimationClass] = useState('animate-fade-in');

  useEffect(() => {
    try {
      const savedHistory = localStorage.getItem('plantHistory');
      if (savedHistory) setHistory(JSON.parse(savedHistory));

      const hasSeenOnboarding = localStorage.getItem('hasSeenOnboarding');
      if (!hasSeenOnboarding) setShowOnboarding(true);

      const savedTheme = localStorage.getItem('theme') as Theme;
      const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
      setTheme(savedTheme || (prefersDark ? 'dark' : 'light'));

    } catch (error) {
      console.error("Failed to parse storage", error);
    }
  }, []);

  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prevTheme => prevTheme === 'dark' ? 'light' : 'dark');
  };

  const handleNavigate = useCallback((view: View, options: { autoUpload?: boolean, feedbackText?: string } = {}) => {
    setAnimationClass('animate-slide-out-to-left');
    setTimeout(() => {
      startNavigation(() => {
        if (view !== 'scan') setScanOptions({});
        else setScanOptions({ autoUpload: options.autoUpload });

        if (view === 'feedback' && options.feedbackText) setPrefilledFeedback(options.feedbackText);
        else if (view !== 'feedback') setPrefilledFeedback('');

        setCurrentView(view);
        setAnimationClass('animate-slide-in-from-right');
      });
    }, 500);
  }, []);

  const handleOnboardingComplete = () => {
    localStorage.setItem('hasSeenOnboarding', 'true');
    setShowOnboarding(false);
  };

  const handleDiagnosisComplete = useCallback((result: Diagnosis, imageSrc: string) => {
    setDiagnosisResult(result);
    setDiagnosisImage(imageSrc);
    handleNavigate('result');
  }, [handleNavigate]);

  const handleSaveDiagnosis = useCallback(() => {
    if (diagnosisResult && diagnosisImage) {
      const newHistoryItem: HistoryItem = {
        ...diagnosisResult,
        id: new Date().toISOString(),
        timestamp: new Date().toISOString(),
        image: diagnosisImage,
      };
      const updatedHistory = [newHistoryItem, ...history];
      setHistory(updatedHistory);
      localStorage.setItem('plantHistory', JSON.stringify(updatedHistory));
      setDiagnosisResult(null);
      setDiagnosisImage(null);
      handleNavigate('history');
    }
  }, [diagnosisResult, diagnosisImage, history, handleNavigate]);

  const handleDiscardDiagnosis = useCallback(() => {
    setDiagnosisResult(null);
    setDiagnosisImage(null);
    handleNavigate('scan');
  }, [handleNavigate]);

  const handleClearHistory = useCallback(() => {
    setHistory([]);
    localStorage.removeItem('plantHistory');
  }, []);

  const renderContent = () => {
    switch (currentView) {
      case 'scan':
        return <ScanScreen onDiagnosisComplete={handleDiagnosisComplete} onNavigate={handleNavigate} autoUpload={scanOptions.autoUpload} />;
      case 'result':
        return diagnosisResult ? (
          <DiagnosisResultScreen 
            diagnosis={diagnosisResult} 
            imageSrc={diagnosisImage} 
            onSave={handleSaveDiagnosis} 
            onDiscard={handleDiscardDiagnosis}
            onReportIncorrect={() => handleNavigate('feedback', { 
              feedbackText: `Incorrect Diagnosis Report:\nPlant: ${diagnosisResult.plantName}\nDetected Issue: ${diagnosisResult.isHealthy ? 'Healthy' : diagnosisResult.disease}\n\nReason for reporting: `
            })}
          />
        ) : <ScanScreen onDiagnosisComplete={handleDiagnosisComplete} onNavigate={handleNavigate} />;
      case 'history':
        return <HistoryScreen history={history} onBack={() => handleNavigate('scan')} onClearHistory={handleClearHistory} />;
      case 'feedback':
        return <FeedbackScreen onBack={() => handleNavigate('scan')} initialComment={prefilledFeedback} />;
      case 'home': // Fallback to scan
      default:
        return <ScanScreen onDiagnosisComplete={handleDiagnosisComplete} onNavigate={handleNavigate} />;
    }
  };

  return (
    <div className="min-h-screen w-full bg-brand-light-bg dark:bg-brand-dark text-brand-light-text dark:text-brand-text font-sans">
      {showOnboarding && <Onboarding onComplete={handleOnboardingComplete} />}
