                    <InfoCard title="Treatment Plan" delay={500}>
                        <Accordion title="Organic Solutions" icon={<LeafIcon className="w-6 h-6 text-green-400" />} defaultOpen={true}>
                            {renderList(diagnosis.treatments.organic)}
                        </Accordion>
                        <Accordion title="Chemical Solutions" icon={<SparklesIcon className="w-6 h-6 text-blue-400" />}>
                            {renderList(diagnosis.treatments.chemical)}
                        </Accordion>
                    </InfoCard>
                    <InfoCard title="Prevention Tips" delay={600}>{renderList(diagnosis.prevention, 700)}</InfoCard>
                </>
            )}

            <div className="pt-4 flex justify-center">
                <button onClick={onReportIncorrect} className="flex items-center gap-2 text-sm font-medium text-orange-400/80 hover:text-orange-300 transition-colors group">
                    <AlertTriangleIcon className="w-4 h-4" /> Report Incorrect Diagnosis
                </button>
            </div>

            <div className="fixed bottom-4 left-1/2 -translate-x-1/2 w-[calc(100%-2rem)] max-w-lg grid grid-cols-3 gap-3 p-2 glass-card-light dark:glass-card-dark rounded-2xl shadow-2xl z-40">
                <button onClick={onDiscard} disabled={saveStatus !== 'idle'} className="ActionButton">
                    <RefreshCwIcon className="w-5 h-5" /> <span>New Scan</span>
                </button>
                <button onClick={handleShare} disabled={saveStatus !== 'idle'} className="ActionButton">
                    <ShareIcon className="w-5 h-5" /> <span>Share</span>
                </button>
                <button onClick={handleAnimatedSave} disabled={saveStatus !== 'idle'} className={`ActionButton text-brand-dark font-bold shadow-lg transition-all ${
                    saveStatus === 'success' ? 'bg-green-400 scale-105 shadow-green-500/30' : 'bg-brand-primary shadow-brand-primary/20 hover:opacity-90'}`}>
                    {saveStatus === 'idle' && <><CheckIcon className="w-5 h-5"/><span>Save</span></>}
                    {saveStatus === 'saving' && <><RefreshCwIcon className="w-5 h-5 animate-spin"/><span>Saving</span></>}
                    {saveStatus === 'success' && <><CheckIcon className="w-5 h-5"/><span>Saved!</span></>}
                </button>
            </div>
        </div>
    );
};

const ActionButton: React.FC<{ children: React.ReactNode; onClick: () => void; disabled: boolean; className?: string }> = ({ children, onClick, disabled, className }) => (
    <button onClick={onClick} disabled={disabled} className={`flex items-center justify-center gap-2 py-3 px-2 rounded-xl bg-brand-light-surface dark:bg-brand-surface hover:bg-black/5 dark:hover:bg-white/10 font-semibold text-xs uppercase tracking-wider transition-all disabled:opacity-50 ${className}`}>
        {children}
    </button>
);

const InfoCard: React.FC<{ title: string; children: React.ReactNode; delay?: number; icon?: React.ReactNode; }> = ({ title, children, delay = 0, icon }) => (
    <div className="glass-card-light dark:glass-card-dark p-6 rounded-2xl animate-fade-in-up" style={{ animationDelay: `${delay}ms` }}>
        <div className="flex items-center gap-3 mb-4">
            {icon}
            <h3 className="text-xl font-bold text-brand-light-text dark:text-white">{title}</h3>
        </div>
        <div className="space-y-4">{children}</div>
    </div>
);

export default DiagnosisResultScreen;

import React, { useState } from 'react';
import { HistoryItem } from '../types';
import { BackArrowIcon, LeafIcon, TrashIcon, CheckCircleIcon, AlertTriangleIcon } from './icons';

interface HistoryScreenProps {
  history: HistoryItem[];
  onBack: () => void;
  onClearHistory: () => void;
}

const HistoryScreen: React.FC<HistoryScreenProps> = ({ history, onBack, onClearHistory }) => {
  const [showConfirm, setShowConfirm] = useState(false);

  const handleClear = () => {
    onClearHistory();
    setShowConfirm(false);
  }

  return (
    <div>
      {showConfirm && (
        <div className="fixed inset-0 z-[100] bg-brand-dark/80 backdrop-blur-md flex items-center justify-center p-4 animate-fade-in">
          <div className="glass-card-dark p-8 rounded-2xl max-w-sm w-full text-center animate-scale-in">
            <h3 className="text-2xl font-bold text-white">Are you sure?</h3>
            <p className="text-brand-text-muted mt-2 mb-6">This will permanently delete all {history.length} of your saved diagnoses.</p>
            <div className="grid grid-cols-2 gap-4">
              <button onClick={() => setShowConfirm(false)} className="py-3 px-4 rounded-lg bg-brand-surface font-semibold hover:bg-white/10 transition-colors">
                Cancel
              </button>
              <button onClick={handleClear} className="py-3 px-4 rounded-lg bg-red-600 text-white font-bold hover:bg-red-500 transition-colors">
                Yes, Clear
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-8">
          <button onClick={onBack} className="flex items-center gap-2 text-brand-light-text-muted dark:text-brand-text-muted hover:text-brand-light-text dark:hover:text-white transition-colors">
              <BackArrowIcon className="w-5 h-5" />
              <span>Scan</span>
          </button>
          <h2 className="font-display text-4xl font-bold text-brand-light-text dark:text-white text-center">My Garden</h2>
           <button
              onClick={() => setShowConfirm(true)}
              disabled={history.length === 0}
              className="flex items-center gap-2 py-2 px-4 rounded-lg text-red-500/80 hover:bg-red-500/10 disabled:opacity-50 transition-colors"
              aria-label="Clear history"
          >
              <TrashIcon className="w-5 h-5" />
              <span className="hidden sm:inline">Clear All</span>
          </button>
      </div>

      {history.length === 0 ? (
        <div className="text-center py-24 px-6 glass-card-light dark:glass-card-dark rounded-2xl">
          <LeafIcon className="w-20 h-20 mx-auto text-brand-primary/20" />
          <h3 className="mt-6 text-2xl font-bold text-brand-light-text dark:text-white">Your Garden History is Empty</h3>
          <p className="mt-2 text-brand-light-text-muted dark:text-brand-text-muted max-w-sm mx-auto">
            Saved diagnoses will appear here. Start by scanning a plant to build your garden's health record.
          </p>
          <button onClick={onBack} className="mt-8 py-3 px-6 bg-brand-primary text-brand-dark font-bold rounded-lg hover:opacity-90 transition-colors shadow-lg shadow-brand-primary/20">
            Start First Scan
          </button>
        </div>
      ) : (
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {history.map((item, index) => (
            <HistoryItemCard key={item.id} item={item} index={index} />
          ))}
        </div>
      )}
    </div>
  );
};

const HistoryItemCard: React.FC<{ item: HistoryItem, index: number }> = ({ item, index }) => {
  const diagnosisDate = new Date(item.timestamp).toLocaleDateString(undefined, {
    month: 'short', day: 'numeric', year: 'numeric'
  });

  return (
    <div className="group glass-card-light dark:glass-card-dark rounded-2xl overflow-hidden shadow-lg transition-all duration-300 hover:!opacity-100 lg:hover:-translate-y-2 lg:hover:shadow-2xl animate-fade-in-up"
         style={{ animationDelay: `${index * 100}ms` }}>
        <div className="relative">
            <img src={item.image} alt={item.plantName} className="w-full h-48 object-cover" />
            <div className="absolute inset-0 bg-gradient-to-t from-black/70 to-transparent"></div>
            <div className="absolute bottom-4 left-4">
                <h4 className="font-bold text-xl text-white">{item.plantName}</h4>
                <p className="text-sm text-brand-text-muted font-medium">{diagnosisDate}</p>
            </div>
            <div className="absolute top-3 right-3 glass-card-dark px-3 py-1 rounded-full text-sm font-bold text-white">
                {Math.round(item.confidence * 100)}%
            </div>
        </div>
        <div className="p-4">
          <div className="flex items-center gap-2">
            {item.isHealthy ? (
                <CheckCircleIcon className="w-5 h-5 text-brand-primary flex-shrink-0" />
            ) : (
                <AlertTriangleIcon className="w-5 h-5 text-orange-400 flex-shrink-0" />
            )}
            <p className={`font-semibold truncate ${item.isHealthy ? 'text-brand-primary' : 'text-orange-400'}`}>
              {item.isHealthy ? 'Healthy' : item.disease}
            </p>
          </div>
        </div>
    </div>
  );
};


export default HistoryScreen;

import React, { useState, useMemo, useEffect } from 'react';
import { BackArrowIcon, StarIcon, CheckIcon } from './icons';

interface FeedbackScreenProps {
    onBack: () => void;
    initialComment?: string;
}

const EMOJI_REACTIONS = [
    { name: 'disappointed', emoji: '😞', label: 'Poor' },
    { name: 'neutral', emoji: '😐', label: 'Average' },
    { name: 'satisfied', emoji: '😊', label: 'Good' },
    { name: 'happy', emoji: '😄', label: 'Great' },
    { name: 'amazed', emoji: '🤩', label: 'Amazing' },
];

const FeedbackScreen: React.FC<FeedbackScreenProps> = ({ onBack, initialComment = '' }) => {
    const [step, setStep] = useState(1);
    const [rating, setRating] = useState(0);
    const [hoverRating, setHoverRating] = useState(0);
    const [reaction, setReaction] = useState<string | null>(null);
    const [comment, setComment] = useState(initialComment);

    const progress = useMemo(() => {
        const completed = [rating > 0, reaction !== null, comment.trim().length > 5].filter(Boolean).length;
        return (completed / 3) * 100;
    }, [rating, reaction, comment]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setStep(2);
    };

    useEffect(() => {
        if (step === 2) {
            const timer = setTimeout(onBack, 3000);
            return () => clearTimeout(timer);
        }
    }, [step, onBack]);

    return (
        <div className="pt-10">
            <button onClick={onBack} className="absolute top-8 left-8 flex items-center gap-2 text-brand-light-text-muted dark:text-brand-text-muted hover:text-brand-light-text dark:hover:text-white transition-colors z-20">
                <BackArrowIcon className="w-5 h-5" />
                <span>Scan</span>
            </button>

            <div className="relative w-full max-w-lg mx-auto glass-card-light dark:glass-card-dark rounded-3xl shadow-2xl overflow-hidden">
                <div className="w-full h-1.5 bg-black/5 dark:bg-brand-surface">
                    <div
                        className="h-full bg-gradient-to-r from-brand-secondary to-brand-primary transition-all duration-500"
                        style={{ width: `${progress}%` }}
                    ></div>
                </div>

                {step === 1 ? (
                    <form onSubmit={handleSubmit} className="p-8 space-y-8">
                        <div className="text-center">
                            <h2 className="font-display text-3xl font-bold text-brand-light-text dark:text-white">Share Your Feedback</h2>
                            <p className="text-brand-light-text-muted dark:text-brand-text-muted mt-1">How was your experience with EcoMed?</p>
                        </div>

                        <div className="space-y-4 text-center">
                            <label className="font-bold text-brand-light-text dark:text-white text-lg">Overall, how would you describe it?</label>
                            <div className="flex justify-around items-center pt-2">
                                {EMOJI_REACTIONS.map(({name, emoji, label}) => (
                                    <div key={name} className="text-center">
                                    <button 
                                        type="button"
                                        onClick={() => setReaction(name)}
                                        className={`p-3 rounded-full text-4xl transition-all duration-200 transform ${reaction === name ? 'bg-brand-primary/20 scale-125' : 'hover:scale-110 hover:bg-black/5 dark:hover:bg-brand-surface'}`}
                                    >
                                        {emoji}
                                    </button>
                                    <span className={`mt-2 text-xs font-bold transition-opacity ${reaction === name ? 'text-brand-primary' : 'text-brand-light-text-muted dark:text-brand-text-muted'}`}>{label}</span>
                                    </div>
                                ))}
                            </div>
                        </div>

                        <div className="space-y-4 text-center">
                             <label className="font-bold text-brand-light-text dark:text-white text-lg">How would you rate our app?</label>
                             <div className="flex justify-center items-center space-x-2 pt-2" onMouseLeave={() => setHoverRating(0)}>
                                {[1, 2, 3, 4, 5].map((star) => (
                                    <StarIcon 
                                        key={star}
                                        className={`w-12 h-12 cursor-pointer transition-all duration-150 transform hover:scale-110 ${ (hoverRating || rating) >= star ? 'text-yellow-400 fill-yellow-400' : 'text-brand-text-muted/30' }`}
                                        onClick={() => setRating(star)}
                                        onMouseEnter={() => setHoverRating(star)}
                                    />
                                ))}
                             </div>
                        </div>

                        <div className="relative">
                            <textarea
                                id="comment"
                                value={comment}
                                onChange={(e) => setComment(e.target.value)}
                                className="peer block w-full h-32 px-4 py-3 bg-brand-light-bg dark:bg-brand-surface rounded-lg border-2 border-transparent focus:border-brand-primary focus:outline-none focus:ring-0 transition-colors text-brand-light-text dark:text-brand-text resize-none"
                                placeholder="Tell us more..."
                            ></textarea>
                        </div>

                        <button type="submit" className="w-full py-4 px-4 rounded-xl bg-gradient-to-r from-brand-secondary to-brand-primary text-brand-dark font-bold text-lg shadow-lg hover:shadow-brand-primary/30 transform hover:scale-105 transition-all duration-300">
                            Submit Feedback
                        </button>
                    </form>
                ) : (
                    <div className="p-8 flex flex-col items-center justify-center text-center h-[34rem] animate-fade-in">
                        <div className="relative w-28 h-28 flex items-center justify-center mb-8">
                            <div className="absolute inset-0 bg-brand-primary/10 rounded-full animate-ping"></div>
                            <div className="w-24 h-24 bg-brand-primary/20 rounded-full flex items-center justify-center">
                                <CheckIcon className="w-16 h-16 text-brand-primary" style={{strokeDasharray: 50, strokeDashoffset: 50, animation: 'draw-check 0.5s 0.2s cubic-bezier(.77,0,.18,1) forwards'}}/>
                            </div>
                        </div>
                        <h2 className="font-display text-4xl font-bold text-brand-light-text dark:text-white">Thank You!</h2>
                        <p className="text-brand-light-text-muted dark:text-brand-text-muted mt-2">Your feedback helps us improve for everyone.</p>
                    </div>
                )}
            </div>
        </div>
    );
};

export default FeedbackScreen;

import React, { useState } from 'react';
import { CameraIcon, SparklesIcon, DatabaseIcon, LeafIcon, CheckIcon, XIcon } from './icons';

interface OnboardingProps {
  onComplete: () => void;
}

const steps = [
  {
    title: "Welcome to EcoMed",
    description: "Your AI companion for professional-grade plant pathology. Let's get you ready to heal your garden.",
    icon: <LeafIcon className="w-16 h-16 text-brand-primary" />,
  },
  {
    title: "Instant Diagnosis",
    description: "Snap a photo of any leaf or plant. Our AI identifies pathologies with scientific precision in milliseconds.",
    icon: <CameraIcon className="w-16 h-16 text-brand-secondary" />,
  },
  {
    title: "Prescriptive Care",
    description: "Receive complete treatment plans including organic solutions and prevention tips.",
    icon: <SparklesIcon className="w-16 h-16 text-emerald-400" />,
  },
  {
    title: "Garden Archive",
    description: "All your scans are saved automatically. Track progress and watch your garden thrive.",
    icon: <DatabaseIcon className="w-16 h-16 text-brand-primary" />,
  }
];

const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [currentStep, setCurrentStep] = useState(0);

  const handleNext = () => {
    if (currentStep < steps.length - 1) {
      setCurrentStep(currentStep + 1);
    } else {
      onComplete();
    }
  };

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-brand-light-bg/80 dark:bg-brand-dark/90 backdrop-blur-xl animate-fade-in">
        <button onClick={onComplete} className="absolute top-6 right-6 w-10 h-10 glass-card-light dark:glass-card-dark rounded-full flex items-center justify-center hover:border-black/20 dark:hover:border-white/20 transition-colors">
            <XIcon className="w-6 h-6 text-brand-light-text-muted dark:text-brand-text-muted" />
        </button>

      <div className="relative w-full max-w-sm glass-card-light dark:glass-card-dark rounded-3xl overflow-hidden shadow-2xl animate-scale-in border border-black/5 dark:border-white/10">
        <div className="p-8 flex flex-col items-center text-center">
            <div className="h-48 flex items-center justify-center">
              {steps.map((step, index) => (
                  <div key={index} className={`transition-all duration-500 absolute ${index === currentStep ? 'opacity-100 scale-100' : 'opacity-0 scale-90'}`}>
                    <div className="animate-float">
                        <div className="relative p-6 bg-brand-light-bg dark:bg-brand-dark/50 rounded-3xl border border-black/10 dark:border-white/10 shadow-2xl">
                            {step.icon}
                        </div>
                        <div className="absolute inset-0 -z-10 bg-brand-primary/10 rounded-full blur-2xl"></div>
                    </div>
                  </div>
              ))}
            </div>

          <h2 className="font-display text-3xl font-black text-brand-light-text dark:text-white mb-4 tracking-tight leading-none h-20">
            {steps[currentStep].title}
          </h2>

          <p className="text-brand-light-text-muted dark:text-brand-text-muted text-lg leading-relaxed font-medium mb-8 h-24">
            {steps[currentStep].description}
          </p>

          <div className="flex items-center gap-2 mb-8">
            {steps.map((_, i) => (
              <div 
                key={i} 
                className={`h-1.5 rounded-full transition-all duration-300 ${i === currentStep ? 'w-6 bg-brand-primary' : 'w-1.5 bg-black/20 dark:bg-white/20'}`}
              />
            ))}
          </div>

          <button
            onClick={handleNext}
            className="w-full py-4 bg-brand-primary text-brand-dark font-black text-lg rounded-xl shadow-lg hover:opacity-90 transition-all flex items-center justify-center gap-2"
          >
            {currentStep === steps.length - 1 ? (
              <>
                <CheckIcon className="w-6 h-6" /> Get Started
              </>
            ) : ( "Continue" )}
          </button>
        </div>
      </div>
    </div>
  );
};

export default Onboarding;

