            <p className="text-brand-text-muted mt-2 mb-6">This will permanently delete all {history.length} of your saved diagnoses.</p>
            <div className="grid grid-cols-2 gap-4">
              <button onClick={() => setShowConfirm(false)} className="py-3 px-4 rounded-lg bg-brand-surface font-semibold hover:bg-white/10 transition-colors">
                Cancel
              </button>
              <button onClick={handleClear} className="py-3 px-4 rounded-lg bg-red-600 text-white font-bold hover:bg-red-500 transition-colors">
                Yes, Clear
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-8">
          <button onClick={onBack} className="flex items-center gap-2 text-brand-light-text-muted dark:text-brand-text-muted hover:text-brand-light-text dark:hover:text-white transition-colors">
              <BackArrowIcon className="w-5 h-5" />
              <span>Home</span>
          </button>
          <h2 className="font-display text-4xl font-bold text-brand-light-text dark:text-white text-center">My Garden</h2>
           <button
              onClick={() => setShowConfirm(true)}
              disabled={history.length === 0}
              className="flex items-center gap-2 py-2 px-4 rounded-lg text-red-500/80 hover:bg-red-500/10 disabled:opacity-50 transition-colors"
              aria-label="Clear history"
          >
              <TrashIcon className="w-5 h-5" />
              <span className="hidden sm:inline">Clear All</span>
          </button>
      </div>

      {history.length === 0 ? (
        <div className="text-center py-24 px-6 glass-card-light dark:glass-card-dark rounded-2xl">
          <LeafIcon className="w-20 h-20 mx-auto text-brand-primary/20" />
          <h3 className="mt-6 text-2xl font-bold text-brand-light-text dark:text-white">Your Garden History is Empty</h3>
          <p className="mt-2 text-brand-light-text-muted dark:text-brand-text-muted max-w-sm mx-auto">
            Saved diagnoses will appear here. Start by scanning a plant to build your garden's health record.
          </p>
          <button onClick={onBack} className="mt-8 py-3 px-6 bg-brand-primary text-brand-dark font-bold rounded-lg hover:opacity-90 transition-colors shadow-lg shadow-brand-primary/20">
            Start First Scan
          </button>
        </div>
      ) : (
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {history.map((item, index) => (
            <HistoryItemCard key={item.id} item={item} index={index} />
          ))}
        </div>
      )}
    </div>
  );
};

const HistoryItemCard: React.FC<{ item: HistoryItem, index: number }> = ({ item, index }) => {
