import React, { useState, useMemo, useEffect } from 'react';
import { BackArrowIcon, StarIcon, CheckIcon } from './icons';

interface FeedbackScreenProps {
    onBack: () => void;
    initialComment?: string;
}

const EMOJI_REACTIONS = [
    { name: 'disappointed', emoji: '😞', label: 'Poor' },
    { name: 'neutral', emoji: '😐', label: 'Average' },
    { name: 'satisfied', emoji: '😊', label: 'Good' },
    { name: 'happy', emoji: '😄', label: 'Great' },
    { name: 'amazed', emoji: '🤩', label: 'Amazing' },
];

const FeedbackScreen: React.FC<FeedbackScreenProps> = ({ onBack, initialComment = '' }) => {
    const [step, setStep] = useState(1);
    const [rating, setRating] = useState(0);
    const [hoverRating, setHoverRating] = useState(0);
    const [reaction, setReaction] = useState<string | null>(null);
    const [comment, setComment] = useState(initialComment);

    const progress = useMemo(() => {
        const completed = [rating > 0, reaction !== null, comment.trim().length > 5].filter(Boolean).length;
        return (completed / 3) * 100;
    }, [rating, reaction, comment]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setStep(2);
    };

    useEffect(() => {
        if (step === 2) {
            const timer = setTimeout(onBack, 3000);
            return () => clearTimeout(timer);
        }
    }, [step, onBack]);

    return (
        <div className="pt-10">
            <button onClick={onBack} className="absolute top-8 left-8 flex items-center gap-2 text-brand-light-text-muted dark:text-brand-text-muted hover:text-brand-light-text dark:hover:text-white transition-colors z-20">
                <BackArrowIcon className="w-5 h-5" />
                <span>Home</span>
            </button>

            <div className="relative w-full max-w-lg mx-auto glass-card-light dark:glass-card-dark rounded-3xl shadow-2xl overflow-hidden">
                <div className="w-full h-1.5 bg-black/5 dark:bg-brand-surface">
                    <div
                        className="h-full bg-gradient-to-r from-brand-secondary to-brand-primary transition-all duration-500"
                        style={{ width: `${progress}%` }}
                    ></div>
                </div>

                {step === 1 ? (
                    <form onSubmit={handleSubmit} className="p-8 space-y-8">
                        <div className="text-center">
                            <h2 className="font-display text-3xl font-bold text-brand-light-text dark:text-white">Share Your Feedback</h2>
                            <p className="text-brand-light-text-muted dark:text-brand-text-muted mt-1">How was your experience with EcoMed?</p>
                        </div>

                        <div className="space-y-4 text-center">
                            <label className="font-bold text-brand-light-text dark:text-white text-lg">Overall, how would you describe it?</label>
                            <div className="flex justify-around items-center pt-2">
                                {EMOJI_REACTIONS.map(({name, emoji, label}) => (
                                    <div key={name} className="text-center">
                                    <button 
                                        type="button"
                                        onClick={() => setReaction(name)}
                                        className={`p-3 rounded-full text-4xl transition-all duration-200 transform ${reaction === name ? 'bg-brand-primary/20 scale-125' : 'hover:scale-110 hover:bg-black/5 dark:hover:bg-brand-surface'}`}
                                    >
                                        {emoji}
                                    </button>
                                    <span className={`mt-2 text-xs font-bold transition-opacity ${reaction === name ? 'text-brand-primary' : 'text-brand-light-text-muted dark:text-brand-text-muted'}`}>{label}</span>
                                    </div>
                                ))}
                            </div>
                        </div>

                        <div className="space-y-4 text-center">
                             <label className="font-bold text-brand-light-text dark:text-white text-lg">How would you rate our app?</label>
                             <div className="flex justify-center items-center space-x-2 pt-2" onMouseLeave={() => setHoverRating(0)}>
                                {[1, 2, 3, 4, 5].map((star) => (
                                    <StarIcon 
                                        key={star}
                                        className={`w-12 h-12 cursor-pointer transition-all duration-150 transform hover:scale-110 ${ (hoverRating || rating) >= star ? 'text-yellow-400 fill-yellow-400' : 'text-brand-text-muted/30' }`}
                                        onClick={() => setRating(star)}
                                        onMouseEnter={() => setHoverRating(star)}
                                    />
                                ))}
                             </div>
                        </div>

                        <div className="relative">
                            <textarea
                                id="comment"
                                value={comment}
                                onChange={(e) => setComment(e.target.value)}
                                className="peer block w-full h-32 px-4 py-3 bg-brand-light-bg dark:bg-brand-surface rounded-lg border-2 border-transparent focus:border-brand-primary focus:outline-none focus:ring-0 transition-colors text-brand-light-text dark:text-brand-text resize-none"
                                placeholder="Tell us more..."
                            ></textarea>
                        </div>

                        <button type="submit" className="w-full py-4 px-4 rounded-xl bg-gradient-to-r from-brand-secondary to-brand-primary text-brand-dark font-bold text-lg shadow-lg hover:shadow-brand-primary/30 transform hover:scale-105 transition-all duration-300">
                            Submit Feedback
                        </button>
                    </form>
                ) : (
                    <div className="p-8 flex flex-col items-center justify-center text-center h-[34rem] animate-fade-in">
                        <div className="relative w-28 h-28 flex items-center justify-center mb-8">
                            <div className="absolute inset-0 bg-brand-primary/10 rounded-full animate-ping"></div>
                            <div className="w-24 h-24 bg-brand-primary/20 rounded-full flex items-center justify-center">
                                <CheckIcon className="w-16 h-16 text-brand-primary" style={{strokeDasharray: 50, strokeDashoffset: 50, animation: 'draw-check 0.5s 0.2s cubic-bezier(.77,0,.18,1) forwards'}}/>
                            </div>
                        </div>
                        <h2 className="font-display text-4xl font-bold text-brand-light-text dark:text-white">Thank You!</h2>
                        <p className="text-brand-light-text-muted dark:text-brand-text-muted mt-2">Your feedback helps us improve for everyone.</p>
                    </div>
                )}
            </div>
        </div>
    );
};

export default FeedbackScreen;

