const DiagnosisResultScreen: React.FC<DiagnosisResultScreenProps> = ({ diagnosis, imageSrc, onSave, onDiscard, onReportIncorrect }) => {
    const [feedback, setFeedback] = useState<{ message: string; type: 'success' | 'error' | 'info' } | null>(null);
    const [curedImage, setCuredImage] = useState<string | null>(null);
    const [isGenerating, setIsGenerating] = useState(false);
    const [generationError, setGenerationError] = useState<string | null>(null);
    const [fullscreenImage, setFullscreenImage] = useState<string | null>(null);
    const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'success'>('idle');

    const confidenceValue = Math.round(diagnosis.confidence * 100);
    const confidenceColor = confidenceValue > 75 ? '#00FF95' : confidenceValue > 50 ? '#f59e0b' : '#ef4444';

    const handleShare = useCallback(async () => {
        // Share logic can be implemented here
    }, [diagnosis, imageSrc, curedImage, confidenceValue]);

    const handleGenerateCured = async () => {
        setIsGenerating(true);
        setGenerationError(null);
        try {
            const url = await generateCuredVision(diagnosis.plantName, diagnosis.disease);
            setCuredImage(url);
        } catch (err: any) {
            setGenerationError("Could not generate visualization. Please try again.");
        } finally {
            setIsGenerating(false);
        }
    };

    const handleAnimatedSave = async () => {
        if (saveStatus !== 'idle') return;
        setSaveStatus('saving');
        await new Promise(resolve => setTimeout(resolve, 800));
        setSaveStatus('success');
        setTimeout(onSave, 1200);
    };

    const renderList = (items: string[], baseDelay: number = 0) => {
        if (!items || items.length === 0) return <p className="italic">No recommendations provided.</p>;
        return (
            <ul className="space-y-4">
                {items.map((item, index) => (
                    <li key={index} className="flex items-start gap-3 opacity-0 animate-fade-in-up"
                        style={{ animationDelay: `${baseDelay + (index * 100)}ms` }}>
                        <CheckIcon className="w-5 h-5 text-brand-primary flex-shrink-0 mt-1" />
                        <span className="leading-relaxed">{item}</span>
                    </li>
                ))}
            </ul>
        );
    };

    return (
        <div className="space-y-6 pb-28">
            {fullscreenImage && (
                <div 
                    className="fixed inset-0 z-[100] bg-brand-light-bg/90 dark:bg-brand-dark/90 backdrop-blur-xl flex items-center justify-center p-4 animate-fade-in"
                    onClick={() => setFullscreenImage(null)}
                >
                    <button className="absolute top-6 right-6 w-10 h-10 glass-card-light dark:glass-card-dark rounded-full flex items-center justify-center" onClick={() => setFullscreenImage(null)}>
                        <XIcon className="w-6 h-6 text-brand-light-text dark:text-white" />
                    </button>
                    <img src={fullscreenImage} alt="Fullscreen view" className="max-w-full max-h-full object-contain rounded-lg shadow-2xl animate-scale-in" />
                </div>
            )}

            <div className="glass-card-light dark:glass-card-dark p-6 rounded-2xl flex flex-col md:flex-row items-center gap-6 text-center md:text-left">
                {imageSrc && (
                    <div className="relative group cursor-zoom-in flex-shrink-0" onClick={() => setFullscreenImage(imageSrc)}>
                        <img src={imageSrc} alt={diagnosis.plantName} className="w-28 h-28 object-cover rounded-xl ring-2 ring-black/10 dark:ring-white/10 transition-transform group-hover:scale-105" />
                    </div>
                )}
                <div className="flex-grow">
                    <h2 className="font-display text-4xl font-bold text-brand-light-text dark:text-white tracking-tight">{diagnosis.plantName}</h2>
                    <div className={`mt-1 text-2xl font-semibold ${diagnosis.isHealthy ? 'text-brand-primary' : 'text-orange-400'}`}>
                        {diagnosis.isHealthy ? 'Healthy' : diagnosis.disease}
                    </div>
                </div>
                {!diagnosis.isHealthy && (
                    <div className="flex-shrink-0">
                        <ConfidenceGauge progress={confidenceValue} color={confidenceColor} />
                    </div>
                )}
            </div>

            {!diagnosis.isHealthy &&
            <InfoCard title="Visualize Healthy Plant" icon={<SparklesIcon className="w-6 h-6 text-brand-secondary" />} delay={200}>
                {curedImage ? (
                    <div className="relative group w-full overflow-hidden rounded-xl cursor-zoom-in animate-scale-in" onClick={() => setFullscreenImage(curedImage)}>
                        <img src={curedImage} alt="AI Generated Cured Vision" className="w-full aspect-square object-cover shadow-2xl transition-transform duration-700 group-hover:scale-105" />
                    </div>
                ) : (
                    <div className="w-full p-8 border-2 border-dashed border-black/10 dark:border-white/10 rounded-xl flex flex-col items-center justify-center bg-brand-light-surface dark:bg-brand-dark/40 hover:border-brand-primary/30 transition-colors">
                        {isGenerating ? (
                            <div className="flex flex-col items-center gap-4 text-center">
                                <SparklesIcon className="w-10 h-10 text-brand-primary animate-spin" />
                                <p className="font-semibold text-brand-primary">AI is visualizing health...</p>
                                <p className="text-sm text-brand-light-text-muted dark:text-brand-text-muted">This can take a few moments.</p>
                            </div>
                        ) : (
                            <>
                                <p className="text-brand-light-text-muted dark:text-brand-text-muted text-center mb-6">See what your plant could look like in a perfect, healthy state.</p>
                                <button onClick={handleGenerateCured} className="px-6 py-2 bg-brand-light-surface dark:bg-brand-surface border border-brand-primary text-brand-primary rounded-lg font-bold hover:bg-brand-primary hover:text-brand-dark transition-all flex items-center gap-2">
                                    <SparklesIcon className="w-5 h-5" /> Visualize
                                </button>
                                {generationError && <p className="mt-4 text-red-400 text-sm">{generationError}</p>}
                            </>
                        )}
                    </div>
                )}
            </InfoCard>
            }

            <InfoCard title="AI Diagnosis Summary" icon={<LeafIcon className="w-6 h-6 text-brand-primary" />} delay={300}>
                <p className="leading-relaxed">{diagnosis.description}</p>
            </InfoCard>

            {!diagnosis.isHealthy && (
                <>
                    <InfoCard title="Symptoms" delay={400}>{renderList(diagnosis.symptoms, 500)}</InfoCard>
                    <InfoCard title="Treatment Plan" delay={500}>
                        <Accordion title="Organic Solutions" icon={<LeafIcon className="w-6 h-6 text-green-400" />} defaultOpen={true}>
                            {renderList(diagnosis.treatments.organic)}
                        </Accordion>
                        <Accordion title="Chemical Solutions" icon={<SparklesIcon className="w-6 h-6 text-blue-400" />}>
                            {renderList(diagnosis.treatments.chemical)}
                        </Accordion>
                    </InfoCard>
                    <InfoCard title="Prevention Tips" delay={600}>{renderList(diagnosis.prevention, 700)}</InfoCard>
                </>
            )}

            <div className="pt-4 flex justify-center">
                <button onClick={onReportIncorrect} className="flex items-center gap-2 text-sm font-medium text-orange-400/80 hover:text-orange-300 transition-colors group">
                    <AlertTriangleIcon className="w-4 h-4" /> Report Incorrect Diagnosis
                </button>
            </div>

            <div className="fixed bottom-4 left-1/2 -translate-x-1/2 w-[calc(100%-2rem)] max-w-lg grid grid-cols-3 gap-3 p-2 glass-card-light dark:glass-card-dark rounded-2xl shadow-2xl z-40">
                <button onClick={onDiscard} disabled={saveStatus !== 'idle'} className="ActionButton">
                    <RefreshCwIcon className="w-5 h-5" /> <span>New Scan</span>
                </button>
                <button onClick={handleShare} disabled={saveStatus !== 'idle'} className="ActionButton">
                    <ShareIcon className="w-5 h-5" /> <span>Share</span>
                </button>
                <button onClick={handleAnimatedSave} disabled={saveStatus !== 'idle'} className={`ActionButton text-brand-dark font-bold shadow-lg transition-all ${
                    saveStatus === 'success' ? 'bg-green-400 scale-105 shadow-green-500/30' : 'bg-brand-primary shadow-brand-primary/20 hover:opacity-90'}`}>
                    {saveStatus === 'idle' && <><CheckIcon className="w-5 h-5"/><span>Save</span></>}
                    {saveStatus === 'saving' && <><RefreshCwIcon className="w-5 h-5 animate-spin"/><span>Saving</span></>}
                    {saveStatus === 'success' && <><CheckIcon className="w-5 h-5"/><span>Saved!</span></>}
                </button>
            </div>
        </div>
    );
};

