import React, { useState, useRef, useEffect, useCallback } from 'react';
import { diagnosePlant } from '../services/geminiService';
import { Diagnosis, View } from '../types';
import { CameraIcon, UploadIcon, SparklesIcon, RefreshCwIcon } from './icons';

interface ScanScreenProps {
  onDiagnosisComplete: (result: Diagnosis, imageSrc: string) => void;
  onNavigate: (view: View, options?: { autoUpload?: boolean }) => void;
  autoUpload?: boolean;
}

const ScanScreen: React.FC<ScanScreenProps> = ({ onDiagnosisComplete, onNavigate, autoUpload }) => {
  const [imageSrc, setImageSrc] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const startCamera = useCallback(async () => {
    try {
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
        const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment', width: 1920, height: 1080 } });
        streamRef.current = stream;
        if (videoRef.current) {
            videoRef.current.srcObject = stream;
        }
    } catch (err) {
        console.error("Error accessing camera:", err);
        setError("Could not access camera. Please grant permission and try again.");
    }
  }, []);

  useEffect(() => {
    if (!imageSrc) {
        startCamera();
    }
    if (autoUpload && fileInputRef.current) {
      fileInputRef.current.click();
    }
    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
    };
  }, [autoUpload, startCamera, imageSrc]);

  const handleCapture = () => {
    if (videoRef.current) {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth;
      canvas.height = videoRef.current.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg');
        setImageSrc(dataUrl);
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
      }
    }
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setImageSrc(e.target?.result as string);
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
      };
      reader.readAsDataURL(file);
    } else {
        if (autoUpload) onNavigate('scan');
    }
  };

  const handleDiagnose = async () => {
    if (!imageSrc) return;
    setIsLoading(true);
    setError(null);
    try {
      const base64Data = imageSrc.split(',')[1];
      const mimeType = imageSrc.match(/data:([a-zA-Z0-9]+\/[a-zA-Z0-9-.+]+).*,.*/)?.[1] || 'image/jpeg';
      const result = await diagnosePlant(base64Data, mimeType);
      onDiagnosisComplete(result, imageSrc);
    } catch (err: any) {
      setError(err.message || 'An unknown error occurred.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleRetake = () => {
      setImageSrc(null);
      setError(null);
      // startCamera will be called by useEffect
  };

  return (
    <div className="flex flex-col items-center justify-center pt-10">
      <div className="w-full max-w-2xl mx-auto glass-card-light dark:glass-card-dark p-2 rounded-2xl shadow-2xl animate-fade-in-up">
        {isLoading ? (
          <div className="flex flex-col items-center justify-center h-[70vh]">
            <div className="relative w-48 h-48">
                <div className="absolute inset-0 border-4 border-brand-primary/20 rounded-full"></div>
                <div className="absolute inset-0 border-4 border-brand-primary rounded-full animate-spin" style={{ clipPath: 'polygon(0 0, 50% 0, 50% 50%, 0 50%)' }}></div>
                <div className="absolute inset-8 bg-brand-primary/10 rounded-full flex items-center justify-center">
                    <SparklesIcon className="w-12 h-12 text-brand-primary animate-pulse" />
                </div>
            </div>
            <h2 className="mt-8 text-2xl font-bold text-brand-light-text dark:text-white">AI is analyzing...</h2>
            <p className="text-brand-light-text-muted dark:text-brand-text-muted">Performing neural scan of plant pathology.</p>
          </div>
        ) : (
          <>
            <div className="relative w-full aspect-[4/3] bg-brand-dark rounded-lg overflow-hidden group">
              {imageSrc ? (
                <img src={imageSrc} alt="Plant for diagnosis" className="w-full h-full object-cover" />
              ) : (
                <>
                    <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover"></video>
                    <div className="absolute inset-0 border-8 border-white/10 rounded-lg pointer-events-none"></div>
                    <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-32 h-32 border-2 border-brand-primary rounded-full opacity-30 group-hover:opacity-60 transition-opacity"></div>
                    <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-1/4 h-[1px] bg-brand-primary opacity-50"></div>
                    <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 h-1/4 w-[1px] bg-brand-primary opacity-50"></div>
                </>
              )}
            </div>

            {error && <div className="bg-red-900/50 border border-red-500 text-red-300 px-4 py-3 rounded-lg my-4" role="alert">{error}</div>}

            <div className="p-4">
            {imageSrc ? (
              <div className="grid grid-cols-2 gap-4">
                <button onClick={handleRetake} className="flex items-center justify-center gap-2 w-full py-4 px-4 rounded-xl bg-brand-light-surface dark:bg-brand-surface hover:bg-black/5 dark:hover:bg-brand-primary/10 text-brand-light-text dark:text-white font-bold transition-colors">
                    <RefreshCwIcon className="w-5 h-5" />
                    Retake
                </button>
                <button onClick={handleDiagnose} className="flex items-center justify-center gap-2 w-full py-4 px-4 rounded-xl bg-brand-primary hover:opacity-90 text-brand-dark font-black text-lg transition-colors">
                  <SparklesIcon className="w-6 h-6"/>
                  Diagnose Plant
                </button>
              </div>
            ) : (
              <div className="grid grid-cols-1 gap-4">
                 <button onClick={handleCapture} className="flex items-center justify-center gap-3 w-full py-4 px-4 rounded-xl bg-brand-primary hover:opacity-90 text-brand-dark font-black text-lg transition-colors shadow-[0_0_30px_-10px_rgba(0,255,149,0.4)]">
                  <CameraIcon className="w-7 h-7"/>
                  Capture Image
                </button>
                <button onClick={() => fileInputRef.current?.click()} className="flex items-center justify-center gap-3 w-full py-3 px-4 rounded-xl bg-brand-light-surface dark:bg-brand-surface hover:bg-black/5 dark:hover:bg-brand-primary/10 text-brand-light-text-muted dark:text-brand-text-muted font-bold transition-colors">
                  <UploadIcon className="w-5 h-5"/>
                  Upload from Library
                </button>
                <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*" className="hidden" />
              </div>
            )}
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default ScanScreen;

