            <ul className="space-y-4">
                {items.map((item, index) => (
                    <li key={index} className="flex items-start gap-3 opacity-0 animate-fade-in-up"
                        style={{ animationDelay: `${baseDelay + (index * 100)}ms` }}>
                        <CheckIcon className="w-5 h-5 text-brand-primary flex-shrink-0 mt-1" />
                        <span className="leading-relaxed">{item}</span>
                    </li>
                ))}
            </ul>
        );
    };

    return (
        <div className="space-y-6 pb-28">
            {fullscreenImage && (
                <div 
                    className="fixed inset-0 z-[100] bg-brand-light-bg/90 dark:bg-brand-dark/90 backdrop-blur-xl flex items-center justify-center p-4 animate-fade-in"
                    onClick={() => setFullscreenImage(null)}
