                {imageSrc && (
                    <div className="relative group cursor-zoom-in flex-shrink-0" onClick={() => setFullscreenImage(imageSrc)}>
                        <img src={imageSrc} alt={diagnosis.plantName} className="w-28 h-28 object-cover rounded-xl ring-2 ring-black/10 dark:ring-white/10 transition-transform group-hover:scale-105" />
                    </div>
                )}
                <div className="flex-grow">
                    <h2 className="font-display text-4xl font-bold text-brand-light-text dark:text-white tracking-tight">{diagnosis.plantName}</h2>
                    <div className={`mt-1 text-2xl font-semibold ${diagnosis.isHealthy ? 'text-brand-primary' : 'text-orange-400'}`}>
                        {diagnosis.isHealthy ? 'Healthy' : diagnosis.disease}
                    </div>
                </div>
                {!diagnosis.isHealthy && (
                    <div className="flex-shrink-0">
                        <ConfidenceGauge progress={confidenceValue} color={confidenceColor} />
                    </div>
                )}
            </div>

            {!diagnosis.isHealthy &&
            <InfoCard title="Visualize Healthy Plant" icon={<SparklesIcon className="w-6 h-6 text-brand-secondary" />} delay={200}>
                {curedImage ? (
                    <div className="relative group w-full overflow-hidden rounded-xl cursor-zoom-in animate-scale-in" onClick={() => setFullscreenImage(curedImage)}>
                        <img src={curedImage} alt="AI Generated Cured Vision" className="w-full aspect-square object-cover shadow-2xl transition-transform duration-700 group-hover:scale-105" />
                    </div>
                ) : (
                    <div className="w-full p-8 border-2 border-dashed border-black/10 dark:border-white/10 rounded-xl flex flex-col items-center justify-center bg-brand-light-surface dark:bg-brand-dark/40 hover:border-brand-primary/30 transition-colors">
                        {isGenerating ? (
                            <div className="flex flex-col items-center gap-4 text-center">
                                <SparklesIcon className="w-10 h-10 text-brand-primary animate-spin" />
                                <p className="font-semibold text-brand-primary">AI is visualizing health...</p>
                                <p className="text-sm text-brand-light-text-muted dark:text-brand-text-muted">This can take a few moments.</p>
                            </div>
                        ) : (
                            <>
                                <p className="text-brand-light-text-muted dark:text-brand-text-muted text-center mb-6">See what your plant could look like in a perfect, healthy state.</p>
                                <button onClick={handleGenerateCured} className="px-6 py-2 bg-brand-light-surface dark:bg-brand-surface border border-brand-primary text-brand-primary rounded-lg font-bold hover:bg-brand-primary hover:text-brand-dark transition-all flex items-center gap-2">
                                    <SparklesIcon className="w-5 h-5" /> Visualize
                                </button>
                                {generationError && <p className="mt-4 text-red-400 text-sm">{generationError}</p>}
                            </>
                        )}
                    </div>
                )}
            </InfoCard>
            }

            <InfoCard title="AI Diagnosis Summary" icon={<LeafIcon className="w-6 h-6 text-brand-primary" />} delay={300}>
                <p className="leading-relaxed">{diagnosis.description}</p>
            </InfoCard>

            {!diagnosis.isHealthy && (
