                    <InfoCard title="Symptoms" delay={400}>{renderList(diagnosis.symptoms, 500)}</InfoCard>
                    <InfoCard title="Treatment Plan" delay={500}>
                        <Accordion title="Organic Solutions" icon={<LeafIcon className="w-6 h-6 text-green-400" />} defaultOpen={true}>
