            </div>

            <div className="fixed bottom-4 left-1/2 -translate-x-1/2 w-[calc(100%-2rem)] max-w-lg grid grid-cols-3 gap-3 p-2 glass-card-light dark:glass-card-dark rounded-2xl shadow-2xl z-40">
