            <p className="text-brand-light-text-muted dark:text-brand-text-muted mt-2 mb-6">This will permanently delete all {history.length} of your saved diagnoses.</p>
            <div className="grid grid-cols-2 gap-4">
              <button onClick={() => setShowConfirm(false)} className="py-3 px-4 rounded-lg bg-brand-light-surface dark:bg-brand-surface font-semibold text-brand-light-text dark:text-white hover:bg-black/5 dark:hover:bg-brand-primary/10 transition-colors">
                Cancel
              </button>
              <button onClick={handleClear} className="py-3 px-4 rounded-lg bg-red-600 text-white font-bold hover:bg-red-500 transition-colors">
                Yes, Clear
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-8">
          <button onClick={onBack} className="flex items-center gap-2 text-brand-light-text-muted dark:text-brand-text-muted hover:text-brand-light-text dark:hover:text-white transition-colors">
              <BackArrowIcon className="w-5 h-5" />
              <span>Home</span>
          </button>
          <h2 className="font-display text-4xl font-bold text-brand-light-text dark:text-white text-center">My Garden</h2>
           <button
              onClick={() => setShowConfirm(true)}
              disabled={history.length === 0}
              className="flex items-center gap-2 py-2 px-4 rounded-lg text-red-500/80 hover:bg-red-500/10 disabled:opacity-50 transition-colors"
              aria-label="Clear history"
          >
              <TrashIcon className="w-5 h-5" />
              <span className="hidden sm:inline">Clear All</span>
          </button>
      </div>

      {history.length === 0 ? (
        <div className="text-center py-24 px-6 glass-card-light dark:glass-card-dark rounded-2xl">
          <LeafIcon className="w-20 h-20 mx-auto text-brand-primary/20" />
          <h3 className="mt-6 text-2xl font-bold text-brand-light-text dark:text-white">Your Garden History is Empty</h3>
          <p className="mt-2 text-brand-light-text-muted dark:text-brand-text-muted max-w-sm mx-auto">
            Saved diagnoses will appear here. Start by scanning a plant to build your garden's health record.
          </p>
          <button onClick={onBack} className="mt-8 py-3 px-6 bg-brand-primary text-brand-dark font-bold rounded-lg hover:opacity-90 transition-colors shadow-lg shadow-brand-primary/20">
            Start First Scan
          </button>
        </div>
      ) : (
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {history.map((item, index) => (
            <HistoryItemCard key={item.id} item={item} index={index} />
          ))}
        </div>
      )}
    </div>
  );
};

const HistoryItemCard: React.FC<{ item: HistoryItem, index: number }> = ({ item, index }) => {
  const diagnosisDate = new Date(item.timestamp).toLocaleDateString(undefined, {
    month: 'short', day: 'numeric', year: 'numeric'
  });

  return (
    <div className="group glass-card-light dark:glass-card-dark rounded-2xl overflow-hidden shadow-lg transition-all duration-300 hover:!opacity-100 lg:hover:-translate-y-2 lg:hover:shadow-2xl animate-fade-in-up"
         style={{ animationDelay: `${index * 100}ms` }}>
        <div className="relative">
            <img src={item.image} alt={item.plantName} className="w-full h-48 object-cover" />
            <div className="absolute inset-0 bg-gradient-to-t from-black/70 to-transparent"></div>
            <div className="absolute bottom-4 left-4">
                <h4 className="font-bold text-xl text-white">{item.plantName}</h4>
                <p className="text-sm text-brand-text-muted font-medium">{diagnosisDate}</p>
            </div>
            <div className="absolute top-3 right-3 glass-card-dark px-3 py-1 rounded-full text-sm font-bold text-white">
                {Math.round(item.confidence * 100)}%
            </div>
        </div>
        <div className="p-4">
          <div className="flex items-center gap-2">
            {item.isHealthy ? (
                <CheckCircleIcon className="w-5 h-5 text-brand-primary flex-shrink-0" />
            ) : (
                <AlertTriangleIcon className="w-5 h-5 text-orange-400 flex-shrink-0" />
            )}
            <p className={`font-semibold truncate ${item.isHealthy ? 'text-brand-primary' : 'text-orange-400'}`}>
              {item.isHealthy ? 'Healthy' : item.disease}
            </p>
          </div>
        </div>
    </div>
  );
};


export default HistoryScreen;
